","/* ============================================================
 GRC VP Command Center — Design Tokens & Theme Foundations
 Alias layer maps to Horizon tokens; GRC semantic palette
 is defined per-theme as rgb triplets (used as rgb(var(--x))).
 ============================================================ */

:root {
 /* GRC semantic palette (rgb triplets) — default = dark executive */
 --grc-critical: 248, 81, 73;
 --grc-high: 245, 158, 11;
 --grc-watch: 234, 179, 8;
 --grc-info: 56, 139, 253;
 --grc-healthy: 46, 204, 113;
 --grc-neutral: 148, 163, 184;
 --grc-ai: 167, 139, 250;
 --grc-track: 71, 85, 105;

 /* Surface + text alias layer */
 --grc-bg: 15, 20, 32;
 --grc-surface: 23, 30, 46;
 --grc-surface-2: 30, 39, 59;
 --grc-surface-raised: 34, 44, 66;
 --grc-border: 44, 56, 82;
 --grc-text: 232, 237, 245;
 --grc-text-muted: 148, 163, 193;
 --grc-text-faint: 108, 122, 150;
 --grc-primary: 56, 139, 253;
 --grc-on-primary: 255, 255, 255;

 --grc-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
 --grc-shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.35);
 --grc-glow: 0 0 0 1px rgba(var(--grc-ai), 0.35), 0 0 24px rgba(var(--grc-ai), 0.18);

 --grc-radius: 14px;
 --grc-radius-sm: 10px;
 --grc-radius-lg: 20px;
 --grc-gap: 1rem;
 --grc-font: var(--now-font-family, "Lato", Arial, sans-serif);
}

/* ---------------- DARK EXECUTIVE MODE ---------------- */
.grc-theme-dark {
 --grc-critical: 248, 81, 73;
 --grc-high: 245, 158, 11;
 --grc-watch: 234, 179, 8;
 --grc-info: 56, 139, 253;
 --grc-healthy: 46, 204, 113;
 --grc-neutral: 148, 163, 184;
 --grc-ai: 167, 139, 250;
 --grc-track: 71, 85, 105;

 --grc-bg: 15, 20, 32;
 --grc-surface: 23, 30, 46;
 --grc-surface-2: 30, 39, 59;
 --grc-surface-raised: 34, 44, 66;
 --grc-border: 44, 56, 82;
 --grc-text: 232, 237, 245;
 --grc-text-muted: 148, 163, 193;
 --grc-text-faint: 108, 122, 150;
 --grc-primary: 56, 139, 253;

 --grc-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
 --grc-shadow-sm: 0 2px 8px rgba(0, 0, 0, 0.35);
}

/* ---------------- LIGHT ENTERPRISE MODE ---------------- */
.grc-theme-light {
 --grc-critical: 214, 48, 49;
 --grc-high: 201, 123, 0;
 --grc-watch: 181, 134, 0;
 --grc-info: 0, 113, 188;
 --grc-healthy: 30, 150, 90;
 --grc-neutral: 100, 116, 139;
 --grc-ai: 124, 92, 219;
 --grc-track: 206, 214, 224;

 --grc-bg: 240, 243, 247;
 --grc-surface: 255, 255, 255;
 --grc-surface-2: 247, 249, 252;
 --grc-surface-raised: 255, 255, 255;
 --grc-border: 222, 228, 236;
 --grc-text: 18, 28, 42;
 --grc-text-muted: 82, 96, 118;
 --grc-text-faint: 130, 144, 165;
 --grc-primary: 0, 113, 188;
 --grc-on-primary: 255, 255, 255;

 --grc-shadow: 0 8px 24px rgba(31, 45, 70, 0.10);
 --grc-shadow-sm: 0 1px 4px rgba(31, 45, 70, 0.08);
 --grc-glow: 0 0 0 1px rgba(var(--grc-ai), 0.30), 0 4px 18px rgba(var(--grc-ai), 0.14);
}

* { box-sizing: border-box; }

html, body {
 margin: 0;
 padding: 0;
 height: 100%;
}

#root {
 min-height: 100vh;
 font-family: var(--grc-font);
 background-color: rgb(var(--grc-bg));
 color: rgb(var(--grc-text));
}

.grc-app {
 min-height: 100vh;
 background:
 radial-gradient(1200px 500px at 85% -10%, rgba(var(--grc-ai), 0.08), transparent 60%),
 radial-gradient(900px 400px at 0% 0%, rgba(var(--grc-primary), 0.07), transparent 55%),
 rgb(var(--grc-bg));
 color: rgb(var(--grc-text));
 display: flex;
 flex-direction: column;
}
","/* ============== Shell, Header, Tabs, Cards, Viz ============== */

.grc-shell { display: flex; flex-direction: column; min-height: 100vh; }
.grc-body { display: flex; flex: 1; min-height: 0; }
.grc-main {
 flex: 1; min-width: 0; padding: 1.25rem 1.5rem 3rem;
 display: flex; flex-direction: column; gap: 1.25rem;
}
.grc-section { display: flex; flex-direction: column; gap: 0.85rem; }
.grc-section__head { display: flex; align-items: center; justify-content: space-between; gap: 1rem; flex-wrap: wrap; }
.grc-section__title { display: flex; align-items: center; gap: 0.55rem; font-size: 1.05rem; font-weight: 700; letter-spacing: 0.1px; }
.grc-section__title small { font-weight: 500; color: rgb(var(--grc-text-muted)); font-size: 0.8rem; }
.grc-section__sub { color: rgb(var(--grc-text-muted)); font-size: 0.85rem; }

/* ---------------- Header ---------------- */
.grc-header {
 display: flex; align-items: center; gap: 1rem; padding: 0.6rem 1.25rem;
 background: linear-gradient(180deg, rgba(var(--grc-surface), 0.95), rgba(var(--grc-surface-2), 0.88));
 border-bottom: 1px solid rgb(var(--grc-border));
 backdrop-filter: blur(8px); position: sticky; top: 0; z-index: 40;
}
.grc-logo { display: flex; align-items: center; gap: 0.6rem; }
.grc-logo__mark {
 width: 38px; height: 38px; border-radius: 10px; display: grid; place-items: center; font-weight: 800;
 color: rgb(var(--grc-on-primary)); background: linear-gradient(135deg, rgb(var(--grc-primary)), rgb(var(--grc-ai)));
 box-shadow: var(--grc-shadow-sm); letter-spacing: 0.5px; font-size: 0.95rem;
}
.grc-logo__text { display: flex; flex-direction: column; line-height: 1.1; }
.grc-logo__title { font-weight: 800; font-size: 0.98rem; }
.grc-logo__sub { font-size: 0.68rem; color: rgb(var(--grc-text-muted)); letter-spacing: 0.2px; }

.grc-header__center { display: flex; align-items: center; gap: 0.5rem; flex: 1; justify-content: center; flex-wrap: wrap; }
.grc-header__right { display: flex; align-items: center; gap: 0.3rem; }

.grc-sel { display: flex; flex-direction: column; gap: 2px; }
.grc-sel__label { font-size: 0.6rem; text-transform: uppercase; letter-spacing: 0.6px; color: rgb(var(--grc-text-faint)); padding-left: 2px; }
.grc-sel__control {
 display: flex; align-items: center; gap: 0.35rem; cursor: pointer; user-select: none;
 background: rgba(var(--grc-surface-raised), 0.9); border: 1px solid rgb(var(--grc-border));
 border-radius: 999px; padding: 0.28rem 0.6rem; font-size: 0.78rem; color: rgb(var(--grc-text));
 transition: border-color 120ms ease, background 120ms ease;
}
.grc-sel__control:hover { border-color: rgba(var(--grc-primary), 0.7); }
.grc-sel__control now-icon { color: rgb(var(--grc-text-muted)); }
.grc-menu {
 position: absolute; top: calc(100% + 6px); left: 0; z-index: 60; min-width: 200px; max-height: 320px; overflow-y: auto;
 background: rgb(var(--grc-surface-raised)); border: 1px solid rgb(var(--grc-border)); border-radius: 12px;
 box-shadow: var(--grc-shadow); padding: 0.3rem;
}
.grc-menu__item {
 display: flex; align-items: center; gap: 0.45rem; width: 100%; text-align: left; cursor: pointer;
 background: transparent; border: none; border-radius: 8px; padding: 0.4rem 0.5rem; font-size: 0.8rem; color: rgb(var(--grc-text));
}
.grc-menu__item:hover { background: rgba(var(--grc-primary), 0.12); }
.grc-menu__item.is-active { color: rgb(var(--grc-primary)); font-weight: 600; }
.grc-menu__item now-icon { color: rgb(var(--grc-primary)); }

.grc-iconbtn {
 position: relative; display: inline-grid; place-items: center; width: 34px; height: 34px;
 border-radius: 9px; border: 1px solid transparent; background: transparent; color: rgb(var(--grc-text-muted));
 cursor: pointer; transition: background 120ms ease, color 120ms ease, border-color 120ms ease;
}
.grc-iconbtn:hover { background: rgba(var(--grc-surface-raised), 0.9); color: rgb(var(--grc-text)); border-color: rgb(var(--grc-border)); }
.grc-iconbtn__badge {
 position: absolute; top: -2px; right: -2px; min-width: 16px; height: 16px; padding: 0 4px;
 border-radius: 999px; background: rgb(var(--grc-critical)); color: #fff; font-size: 0.6rem; font-weight: 700;
 display: grid; place-items: center; border: 2px solid rgb(var(--grc-surface));
}
.grc-updated { font-size: 0.68rem; color: rgb(var(--grc-text-faint)); white-space: nowrap; padding: 0 0.4rem; }
.grc-avatar {
 width: 32px; height: 32px; border-radius: 50%; display: grid; place-items: center; font-size: 0.72rem; font-weight: 700;
 background: linear-gradient(135deg, rgb(var(--grc-ai)), rgb(var(--grc-primary))); color: #fff;
}
.grc-ai-btn {
 display: inline-flex; align-items: center; gap: 0.4rem; border-radius: 999px; cursor: pointer;
 padding: 0.32rem 0.7rem; font-size: 0.78rem; font-weight: 600; color: rgb(var(--grc-ai));
 background: rgba(var(--grc-ai), 0.12); border: 1px solid rgba(var(--grc-ai), 0.45);
}
.grc-ai-btn:hover { background: rgba(var(--grc-ai), 0.2); }

/* ---------------- Tab nav ---------------- */
.grc-tabs {
 display: flex; gap: 0.15rem; padding: 0 1rem; background: rgba(var(--grc-surface), 0.6);
 border-bottom: 1px solid rgb(var(--grc-border)); overflow-x: auto; position: sticky; top: 52px; z-index: 30;
}
.grc-tab {
 display: inline-flex; align-items: center; gap: 0.45rem; padding: 0.7rem 0.95rem; cursor: pointer;
 color: rgb(var(--grc-text-muted)); font-size: 0.82rem; font-weight: 600; white-space: nowrap;
 border: none; background: transparent; border-bottom: 2px solid transparent; transition: color 120ms ease;
}
.grc-tab:hover { color: rgb(var(--grc-text)); }
.grc-tab--active { color: rgb(var(--grc-text)); border-bottom-color: rgb(var(--grc-primary)); }
.grc-theme-dark .grc-tab--active {
 border-bottom-color: rgb(var(--grc-ai));
 text-shadow: 0 0 14px rgba(var(--grc-ai), 0.5);
}

/* ---------------- Breadcrumbs ---------------- */
.grc-crumbs { display: flex; align-items: center; gap: 0.4rem; font-size: 0.78rem; color: rgb(var(--grc-text-muted)); }
.grc-crumbs button { background: none; border: none; color: rgb(var(--grc-primary)); cursor: pointer; font-size: 0.78rem; padding: 0; }
.grc-crumbs button:hover { text-decoration: underline; }

/* ---------------- Card base ---------------- */
.grc-card {
 background: linear-gradient(180deg, rgba(var(--grc-surface), 0.96), rgba(var(--grc-surface-2), 0.92));
 border: 1px solid rgb(var(--grc-border)); border-radius: var(--grc-radius);
 box-shadow: var(--grc-shadow-sm); padding: 1rem 1.1rem; position: relative; overflow: hidden;
}
.grc-card--pad0 { padding: 0; }
.grc-card--click { cursor: pointer; transition: transform 140ms ease, box-shadow 140ms ease, border-color 140ms ease; }
.grc-card--click:hover { transform: translateY(-3px); box-shadow: var(--grc-shadow); border-color: rgba(var(--grc-primary), 0.55); }
.grc-card__accent { position: absolute; left: 0; top: 0; bottom: 0; width: 4px; }
.grc-card__head { display: flex; align-items: center; justify-content: space-between; gap: 0.6rem; margin-bottom: 0.6rem; }
.grc-card__title { font-weight: 700; font-size: 0.92rem; display: flex; align-items: center; gap: 0.45rem; }
.grc-card__hint { font-size: 0.75rem; color: rgb(var(--grc-text-muted)); }

.grc-grid { display: grid; gap: var(--grc-gap); }
.grc-metric { display: flex; flex-direction: column; gap: 2px; }
.grc-metric__label { font-size: 0.68rem; color: rgb(var(--grc-text-muted)); text-transform: uppercase; letter-spacing: 0.4px; }
.grc-metric__value { font-size: 1.1rem; font-weight: 700; }

/* ---------------- Pills / trend / confidence / dot ---------------- */
.grc-pill {
 display: inline-flex; align-items: center; gap: 0.3rem; border-radius: 999px; font-weight: 600; line-height: 1;
 padding: 0.22rem 0.55rem; font-size: 0.72rem; color: rgb(var(--grc-text));
 background: rgba(var(--pill-c-rgb, 148,163,184), 0.14);
 border: 1px solid var(--pill-c); box-shadow: inset 0 0 0 9999px rgba(0,0,0,0);
}
.grc-pill now-icon { color: var(--pill-c); }
.grc-pill--sm { font-size: 0.66rem; padding: 0.15rem 0.45rem; }

.grc-trend { display: inline-flex; align-items: center; gap: 0.25rem; font-size: 0.76rem; font-weight: 600; }
.grc-trend--up { color: rgb(var(--grc-critical)); }
.grc-trend--down { color: rgb(var(--grc-healthy)); }
.grc-trend--flat { color: rgb(var(--grc-text-muted)); }

.grc-confidence { display: inline-flex; align-items: center; gap: 0.35rem; font-size: 0.72rem; color: rgb(var(--grc-ai)); font-weight: 600; }
.grc-confidence__track { width: 54px; height: 5px; border-radius: 999px; background: rgba(var(--grc-track), 0.6); overflow: hidden; }
.grc-confidence__fill { display: block; height: 100%; background: rgb(var(--grc-ai)); }
.grc-dot { width: 9px; height: 9px; border-radius: 50%; display: inline-block; }

/* ---------------- Viz primitives ---------------- */
.grc-gauge, .grc-ring, .grc-donut { position: relative; display: inline-grid; place-items: center; }
.grc-gauge svg, .grc-ring svg, .grc-donut svg { position: absolute; inset: 0; }
.grc-gauge__center, .grc-donut__center { position: relative; text-align: center; display: flex; flex-direction: column; }
.grc-gauge__value { font-size: 1.5rem; font-weight: 800; }
.grc-gauge__sub { font-size: 0.66rem; color: rgb(var(--grc-text-muted)); letter-spacing: 0.5px; text-transform: uppercase; }
.grc-ring__text { position: relative; font-size: 0.8rem; font-weight: 700; }
.grc-gauge__arc, .grc-ring__arc { transition: stroke-dashoffset 700ms ease; }

.grc-spark, .grc-bars { display: block; width: 100%; height: auto; }
.grc-minibar { display: inline-block; width: 100%; background: rgba(var(--grc-track), 0.6); border-radius: 999px; overflow: hidden; vertical-align: middle; }
.grc-minibar__fill { display: block; height: 100%; border-radius: 999px; }

.grc-heatmap { display: block; }
.grc-heatmap__bubble { cursor: pointer; }
.grc-heatmap__bubble:hover circle { filter: brightness(1.15); }
.grc-heatmap__label { font-size: 9px; fill: rgb(var(--grc-text-muted)); font-weight: 600; }
.grc-heatmap__axis { font-size: 11px; fill: rgb(var(--grc-text-faint)); font-weight: 600; }

.grc-miniheat { display: grid; grid-template-columns: repeat(3, 1fr); gap: 3px; width: 54px; height: 54px; }
.grc-miniheat span { border-radius: 3px; }
","/* ================= Overview sections, drawer, AI ================= */

/* Hero */
.grc-hero { display: grid; grid-template-columns: 1fr 1.4fr 0.9fr; gap: 1rem; }
.grc-hero__posture { display: flex; gap: 1rem; align-items: center; }
.grc-hero__posture-txt { display: flex; flex-direction: column; gap: 0.4rem; }
.grc-hero__score { font-size: 1.1rem; font-weight: 800; display: flex; align-items: baseline; gap: 0.4rem; }
.grc-hero__score b { font-size: 2rem; }
.grc-hero__blurb { font-size: 0.82rem; color: rgb(var(--grc-text-muted)); line-height: 1.45; }

/* AI brief */
.grc-aibrief {
 border: 1px solid rgba(var(--grc-ai), 0.5);
 background: linear-gradient(180deg, rgba(var(--grc-ai), 0.12), rgba(var(--grc-surface-2), 0.9));
}
.grc-theme-dark .grc-aibrief { box-shadow: var(--grc-glow); }
.grc-aibrief__tag { display: inline-flex; align-items: center; gap: 0.4rem; color: rgb(var(--grc-ai)); font-weight: 800; font-size: 0.8rem; letter-spacing: 0.3px; }
.grc-aibrief__body { font-size: 0.84rem; line-height: 1.5; color: rgb(var(--grc-text)); margin: 0.5rem 0; }
.grc-aibrief__list { margin: 0.4rem 0; padding: 0; list-style: none; display: flex; flex-direction: column; gap: 0.3rem; }
.grc-aibrief__list li { display: flex; gap: 0.5rem; font-size: 0.82rem; color: rgb(var(--grc-text-muted)); }
.grc-aibrief__list li::before { content: "▸"; color: rgb(var(--grc-ai)); }
.grc-aibrief__rec { font-size: 0.82rem; font-weight: 600; border-left: 3px solid rgb(var(--grc-ai)); padding-left: 0.6rem; margin: 0.5rem 0; }
.grc-aibrief__actions { display: flex; flex-wrap: wrap; gap: 0.4rem; margin-top: 0.6rem; }

/* Attention list */
.grc-attn { display: flex; flex-direction: column; gap: 0.5rem; }
.grc-attn__row { display: flex; align-items: center; justify-content: space-between; gap: 0.5rem; padding: 0.5rem 0.65rem; border-radius: 10px; background: rgba(var(--grc-surface-raised), 0.6); border: 1px solid rgb(var(--grc-border)); }
.grc-attn__left { display: flex; align-items: center; gap: 0.5rem; font-size: 0.82rem; }
.grc-attn__val { font-size: 1.2rem; font-weight: 800; }

/* KPI strip */
.grc-kpis { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }
.grc-kpi { display: flex; flex-direction: column; gap: 0.5rem; min-height: 128px; }
.grc-kpi__top { display: flex; align-items: flex-start; justify-content: space-between; gap: 0.5rem; }
.grc-kpi__title { font-size: 0.74rem; font-weight: 700; color: rgb(var(--grc-text-muted)); text-transform: uppercase; letter-spacing: 0.3px; }
.grc-kpi__value { font-size: 1.7rem; font-weight: 800; line-height: 1; }
.grc-kpi__change { font-size: 0.74rem; color: rgb(var(--grc-text-muted)); }
.grc-kpi__viz { margin-top: auto; display: flex; align-items: center; justify-content: space-between; gap: 0.5rem; }
.grc-kpi__foot { font-size: 0.68rem; color: rgb(var(--grc-text-faint)); }
.grc-kpi__dist { display: flex; gap: 4px; align-items: flex-end; height: 36px; }
.grc-kpi__dist span { width: 14px; border-radius: 3px 3px 0 0; }

/* Risk landscape */
.grc-landscape { display: grid; grid-template-columns: 2fr 1fr; gap: 1rem; align-items: start; }
.grc-appetite__row { display: flex; flex-direction: column; gap: 0.3rem; padding: 0.6rem 0; border-bottom: 1px dashed rgb(var(--grc-border)); }
.grc-appetite__row:last-child { border-bottom: none; }
.grc-appetite__top { display: flex; align-items: center; justify-content: space-between; gap: 0.5rem; }
.grc-appetite__name { font-weight: 700; font-size: 0.86rem; display: flex; align-items: center; gap: 0.4rem; }
.grc-appetite__score { font-weight: 800; font-size: 1rem; }
.grc-appetite__meta { display: flex; align-items: center; justify-content: space-between; gap: 0.5rem; font-size: 0.74rem; color: rgb(var(--grc-text-muted)); }
.grc-predict { margin-top: 0.7rem; padding: 0.6rem 0.7rem; border-radius: 10px; font-size: 0.8rem; display: flex; gap: 0.5rem; align-items: flex-start;
 background: rgba(var(--grc-ai), 0.12); border: 1px solid rgba(var(--grc-ai), 0.4); color: rgb(var(--grc-text)); }
.grc-predict now-icon { color: rgb(var(--grc-ai)); }
.grc-legend { display: flex; flex-wrap: wrap; gap: 0.6rem; font-size: 0.72rem; color: rgb(var(--grc-text-muted)); margin-top: 0.5rem; }
.grc-legend span { display: inline-flex; align-items: center; gap: 0.3rem; }

/* Domain pulse */
.grc-pulse { display: grid; grid-template-columns: repeat(5, 1fr); gap: 1rem; }
.grc-pulse__card { display: flex; flex-direction: column; gap: 0.6rem; }
.grc-pulse__metrics { display: flex; flex-direction: column; gap: 0.35rem; }
.grc-pulse__metric { display: flex; align-items: center; justify-content: space-between; font-size: 0.78rem; }
.grc-pulse__metric b { font-weight: 800; }
.grc-pulse__viz { display: flex; align-items: center; justify-content: center; min-height: 56px; }

/* Assurance */
.grc-assurance { display: grid; grid-template-columns: 2fr 1fr; gap: 1rem; align-items: start; }
.grc-matrix { width: 100%; border-collapse: collapse; font-size: 0.8rem; }
.grc-matrix th, .grc-matrix td { padding: 0.55rem 0.6rem; text-align: center; border-bottom: 1px solid rgb(var(--grc-border)); }
.grc-matrix th:first-child, .grc-matrix td:first-child { text-align: left; font-weight: 600; }
.grc-matrix thead th { color: rgb(var(--grc-text-muted)); font-size: 0.72rem; text-transform: uppercase; letter-spacing: 0.3px; }
.grc-cell { display: inline-flex; align-items: center; gap: 0.3rem; padding: 0.2rem 0.5rem; border-radius: 999px; font-size: 0.7rem; font-weight: 600; }
.grc-cell--covered { background: rgba(var(--grc-healthy), 0.16); color: rgb(var(--grc-healthy)); border: 1px solid rgba(var(--grc-healthy), 0.5); }
.grc-cell--partial { background: rgba(var(--grc-watch), 0.16); color: rgb(var(--grc-watch)); border: 1px solid rgba(var(--grc-watch), 0.5); }
.grc-cell--gap { background: rgba(var(--grc-critical), 0.16); color: rgb(var(--grc-critical)); border: 1px solid rgba(var(--grc-critical), 0.5); }
.grc-cell--planned { background: rgba(var(--grc-info), 0.16); color: rgb(var(--grc-info)); border: 1px solid rgba(var(--grc-info), 0.5); }
.grc-assurance__side { display: flex; flex-direction: column; gap: 0.8rem; }
.grc-bigmetric { text-align: center; }
.grc-bigmetric__value { font-size: 2.6rem; font-weight: 800; line-height: 1; }
.grc-bigmetric__label { font-size: 0.76rem; color: rgb(var(--grc-text-muted)); }
.grc-statgrid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0.6rem; }
.grc-statgrid .grc-metric { padding: 0.5rem; border-radius: 10px; background: rgba(var(--grc-surface-raised), 0.6); border: 1px solid rgb(var(--grc-border)); align-items: center; text-align: center; }

/* AI inline insight banner */
.grc-ailine { display: flex; gap: 0.5rem; align-items: flex-start; font-size: 0.8rem; padding: 0.6rem 0.7rem; border-radius: 10px;
 background: rgba(var(--grc-ai), 0.1); border: 1px solid rgba(var(--grc-ai), 0.4); }
.grc-ailine now-icon { color: rgb(var(--grc-ai)); }

/* Control + remediation */
.grc-two { display: grid; grid-template-columns: 1fr 1fr; gap: 1rem; align-items: start; }
.grc-donut-legend { display: flex; flex-direction: column; gap: 0.4rem; }
.grc-donut-legend__row { display: flex; align-items: center; justify-content: space-between; font-size: 0.8rem; gap: 0.5rem; }
.grc-donut-row { display: flex; align-items: center; gap: 1rem; }
.grc-problems { display: flex; flex-direction: column; gap: 0.5rem; }
.grc-problems__row { display: grid; grid-template-columns: 100px 1fr 34px; gap: 0.5rem; align-items: center; font-size: 0.78rem; }
.grc-kpi-mini { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0.6rem; }
.grc-kpi-mini .grc-metric { padding: 0.5rem; border-radius: 10px; background: rgba(var(--grc-surface-raised), 0.5); }
.grc-note { font-size: 0.78rem; color: rgb(var(--grc-watch)); display: flex; gap: 0.4rem; align-items: center; margin-top: 0.5rem; }

/* Regulatory timeline */
.grc-timeline { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; }
.grc-regcard { display: flex; flex-direction: column; gap: 0.5rem; }
.grc-regcard__tag { align-self: flex-start; }
.grc-regcard__title { font-weight: 700; font-size: 0.9rem; }
.grc-regcard__detail { font-size: 0.8rem; color: rgb(var(--grc-text-muted)); line-height: 1.45; }
.grc-regcard__meta { font-size: 0.72rem; color: rgb(var(--grc-text-faint)); display: flex; align-items: center; gap: 0.5rem; }
.grc-regcard__actions { display: flex; gap: 0.4rem; flex-wrap: wrap; margin-top: auto; }

/* Policy / governance */
.grc-funnel { display: flex; flex-direction: column; gap: 0.4rem; }
.grc-funnel__row { display: grid; grid-template-columns: 130px 1fr 42px; align-items: center; gap: 0.5rem; font-size: 0.8rem; }
.grc-chain { display: flex; align-items: center; justify-content: center; gap: 0.5rem; flex-wrap: wrap; padding: 0.6rem; }
.grc-chain__node { display: flex; flex-direction: column; align-items: center; gap: 0.3rem; padding: 0.5rem 0.7rem; border-radius: 10px; font-size: 0.72rem; font-weight: 600;
 border: 1px solid rgb(var(--grc-border)); background: rgba(var(--grc-surface-raised), 0.6); }
.grc-chain__arrow { color: rgb(var(--grc-text-faint)); }

/* Issues table */
.grc-table { width: 100%; border-collapse: collapse; font-size: 0.8rem; }
.grc-table thead th { text-align: left; padding: 0.6rem 0.7rem; font-size: 0.68rem; text-transform: uppercase; letter-spacing: 0.3px;
 color: rgb(var(--grc-text-muted)); border-bottom: 1px solid rgb(var(--grc-border)); position: sticky; top: 0; background: rgba(var(--grc-surface), 0.95); }
.grc-table tbody td { padding: 0.6rem 0.7rem; border-bottom: 1px solid rgb(var(--grc-border)); vertical-align: middle; }
.grc-table tbody tr { cursor: pointer; transition: background 120ms ease; }
.grc-table tbody tr:hover { background: rgba(var(--grc-primary), 0.08); }
.grc-table__ai { color: rgb(var(--grc-ai)); display: inline-flex; gap: 0.35rem; align-items: center; }
.grc-exposure { font-weight: 700; }

/* Change feed */
.grc-feed { display: flex; flex-direction: column; }
.grc-feed__row { display: flex; gap: 0.7rem; padding: 0.55rem 0; position: relative; }
.grc-feed__icon { width: 30px; height: 30px; border-radius: 50%; display: grid; place-items: center; flex-shrink: 0;
 background: rgba(var(--grc-surface-raised), 0.9); border: 1px solid rgb(var(--grc-border)); }
.grc-feed__txt { font-size: 0.82rem; }
.grc-feed__line { position: absolute; left: 15px; top: 36px; bottom: -8px; width: 1px; background: rgb(var(--grc-border)); }
.grc-toggle { display: inline-flex; border: 1px solid rgb(var(--grc-border)); border-radius: 999px; overflow: hidden; }
.grc-toggle button { background: transparent; border: none; padding: 0.3rem 0.7rem; font-size: 0.74rem; color: rgb(var(--grc-text-muted)); cursor: pointer; }
.grc-toggle button.is-active { background: rgb(var(--grc-primary)); color: #fff; }

/* BU performance */
.grc-bu-table td, .grc-bu-table th { padding: 0.55rem 0.7rem; }
.grc-bu-trend { display: inline-flex; }

/* Drawer */
.grc-drawer-overlay { position: fixed; inset: 0; background: rgba(0, 0, 0, 0.5); z-index: 80; animation: grc-fade 160ms ease; }
.grc-drawer { position: fixed; top: 0; right: 0; bottom: 0; width: min(560px, 94vw); z-index: 81;
 background: rgb(var(--grc-surface)); border-left: 1px solid rgb(var(--grc-border)); box-shadow: var(--grc-shadow);
 display: flex; flex-direction: column; animation: grc-slide 220ms ease; }
.grc-drawer__head { padding: 1rem 1.1rem; border-bottom: 1px solid rgb(var(--grc-border)); display: flex; justify-content: space-between; gap: 0.6rem; align-items: flex-start; }
.grc-drawer__title { font-size: 1.05rem; font-weight: 800; }
.grc-drawer__body { padding: 1rem 1.1rem; overflow-y: auto; display: flex; flex-direction: column; gap: 0.9rem; }
.grc-drawer__foot { padding: 0.8rem 1.1rem; border-top: 1px solid rgb(var(--grc-border)); display: flex; flex-wrap: wrap; gap: 0.4rem; background: rgba(var(--grc-surface-2), 0.7); }
.grc-field { display: flex; flex-direction: column; gap: 2px; }
.grc-field__label { font-size: 0.66rem; text-transform: uppercase; letter-spacing: 0.4px; color: rgb(var(--grc-text-faint)); }
.grc-field__value { font-size: 0.84rem; }
.grc-fieldgrid { display: grid; grid-template-columns: 1fr 1fr; gap: 0.7rem; }
.grc-aiblock { border: 1px solid rgba(var(--grc-ai), 0.4); border-radius: 12px; padding: 0.8rem; background: rgba(var(--grc-ai), 0.08); display: flex; flex-direction: column; gap: 0.6rem; }
.grc-aiqa__q { font-weight: 700; font-size: 0.8rem; display: flex; gap: 0.4rem; align-items: center; color: rgb(var(--grc-ai)); }
.grc-aiqa__a { font-size: 0.8rem; color: rgb(var(--grc-text-muted)); margin: 0.15rem 0 0; line-height: 1.45; }
.grc-chips { display: flex; flex-wrap: wrap; gap: 0.35rem; }
.grc-chip { font-size: 0.72rem; padding: 0.2rem 0.5rem; border-radius: 8px; background: rgba(var(--grc-surface-raised), 0.8); border: 1px solid rgb(var(--grc-border)); display: inline-flex; gap: 0.3rem; align-items: center; }

/* AI side panel */
.grc-aipanel { width: 340px; flex-shrink: 0; border-left: 1px solid rgb(var(--grc-border)); background: rgba(var(--grc-surface), 0.75);
 display: flex; flex-direction: column; position: sticky; top: 90px; align-self: flex-start; height: calc(100vh - 90px); }
.grc-aipanel--collapsed { width: 46px; }
.grc-aipanel__head { padding: 0.8rem; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid rgb(var(--grc-border)); }
.grc-aipanel__title { display: flex; align-items: center; gap: 0.4rem; font-weight: 800; font-size: 0.85rem; color: rgb(var(--grc-ai)); }
.grc-aipanel__body { padding: 0.8rem; overflow-y: auto; display: flex; flex-direction: column; gap: 0.7rem; }
.grc-insight { border-radius: 12px; padding: 0.7rem; border: 1px solid rgb(var(--grc-border)); background: rgba(var(--grc-surface-raised), 0.7); display: flex; flex-direction: column; gap: 0.4rem; }
.grc-insight--critical { border-left: 3px solid rgb(var(--grc-critical)); }
.grc-insight--high { border-left: 3px solid rgb(var(--grc-high)); }
.grc-insight--watch { border-left: 3px solid rgb(var(--grc-watch)); }
.grc-insight--info { border-left: 3px solid rgb(var(--grc-info)); }
.grc-insight__type { font-size: 0.64rem; font-weight: 800; letter-spacing: 0.5px; color: rgb(var(--grc-ai)); display: flex; align-items: center; gap: 0.3rem; }
.grc-insight__title { font-size: 0.82rem; font-weight: 600; line-height: 1.35; }
.grc-insight__reason { font-size: 0.74rem; color: rgb(var(--grc-text-muted)); }
.grc-insight__foot { display: flex; align-items: center; justify-content: space-between; gap: 0.4rem; }
.grc-insight__actions { display: flex; gap: 0.3rem; flex-wrap: wrap; }
.grc-collapsed-rail { display: flex; flex-direction: column; align-items: center; gap: 0.8rem; padding-top: 0.8rem; }

/* Floating AI */
.grc-fab { position: fixed; right: 1.2rem; bottom: 1.2rem; z-index: 70; width: 56px; height: 56px; border-radius: 50%;
 border: none; cursor: pointer; display: grid; place-items: center; color: #fff;
 background: linear-gradient(135deg, rgb(var(--grc-ai)), rgb(var(--grc-primary))); box-shadow: var(--grc-shadow); }
.grc-fab:hover { transform: scale(1.05); }
.grc-chatwin { position: fixed; right: 1.2rem; bottom: 5.2rem; z-index: 71; width: min(380px, 92vw); max-height: 70vh;
 background: rgb(var(--grc-surface)); border: 1px solid rgba(var(--grc-ai), 0.4); border-radius: 16px; box-shadow: var(--grc-shadow);
 display: flex; flex-direction: column; overflow: hidden; animation: grc-slideup 200ms ease; }
.grc-chatwin__head { padding: 0.8rem; background: linear-gradient(135deg, rgba(var(--grc-ai), 0.2), rgba(var(--grc-primary), 0.12)); display: flex; justify-content: space-between; align-items: center; }
.grc-chatwin__title { font-weight: 800; font-size: 0.9rem; display: flex; align-items: center; gap: 0.4rem; }
.grc-chatwin__body { padding: 0.8rem; overflow-y: auto; display: flex; flex-direction: column; gap: 0.6rem; }
.grc-chatwin__hint { font-size: 0.76rem; color: rgb(var(--grc-text-muted)); }
.grc-suggest { display: flex; flex-direction: column; gap: 0.35rem; }
.grc-suggest button { text-align: left; background: rgba(var(--grc-surface-raised), 0.8); border: 1px solid rgb(var(--grc-border)); border-radius: 10px;
 padding: 0.5rem 0.6rem; font-size: 0.78rem; color: rgb(var(--grc-text)); cursor: pointer; }
.grc-suggest button:hover { border-color: rgba(var(--grc-ai), 0.6); background: rgba(var(--grc-ai), 0.1); }
.grc-msg { font-size: 0.8rem; padding: 0.5rem 0.65rem; border-radius: 10px; line-height: 1.4; }
.grc-msg--user { align-self: flex-end; background: rgb(var(--grc-primary)); color: #fff; }
.grc-msg--ai { align-self: flex-start; background: rgba(var(--grc-ai), 0.12); border: 1px solid rgba(var(--grc-ai), 0.35); }

/* Placeholder tab */
.grc-placeholder { display: flex; flex-direction: column; gap: 0.5rem; }

@keyframes grc-fade { from { opacity: 0; } to { opacity: 1; } }
@keyframes grc-slide { from { transform: translateX(40px); opacity: 0; } to { transform: translateX(0); opacity: 1; } }
@keyframes grc-slideup { from { transform: translateY(20px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }

/* Responsive */
@media (max-width: 1440px) {
 .grc-hero { grid-template-columns: 1fr 1fr; }
 .grc-hero__attn { grid-column: 1 / -1; }
 .grc-kpis { grid-template-columns: repeat(4, 1fr); }
 .grc-pulse { grid-template-columns: repeat(3, 1fr); }
}
@media (max-width: 1100px) {
 .grc-hero, .grc-landscape, .grc-two, .grc-assurance { grid-template-columns: 1fr; }
 .grc-kpis { grid-template-columns: repeat(2, 1fr); }
 .grc-timeline { grid-template-columns: 1fr; }
 .grc-aipanel { display: none; }
}
@media (max-width: 720px) {
 .grc-kpis, .grc-pulse { grid-template-columns: 1fr; }
 .grc-header__center { display: none; }
}

/* ===== KPI drawer additions (Prompt-2 integration layer) ===== */
.grc-drawer__kpival { font-size: 1.5rem; font-weight: 800; line-height: 1; }

/* Threshold bar */
.grc-thbar { display: flex; flex-direction: column; gap: 0.4rem; }
.grc-thbar__track { position: relative; height: 10px; border-radius: 999px; background: rgba(var(--grc-track), 0.4); overflow: visible; }
.grc-thbar__fill { position: absolute; left: 0; top: 0; bottom: 0; border-radius: 999px; opacity: 0.9; }
.grc-thbar__tick { position: absolute; top: -3px; width: 2px; height: 16px; border-radius: 2px; transform: translateX(-1px); }
.grc-thbar__tick--t { background: rgb(var(--grc-healthy)); }
.grc-thbar__tick--w { background: rgb(var(--grc-watch)); }
.grc-thbar__tick--c { background: rgb(var(--grc-critical)); }
.grc-thbar__legend { display: flex; flex-wrap: wrap; gap: 0.7rem; font-size: 0.7rem; color: rgb(var(--grc-text-muted)); }

/* Driver rows */
.grc-drivers { display: grid; grid-template-columns: repeat(2, 1fr); gap: 0.5rem; }
.grc-driver { display: flex; align-items: center; justify-content: space-between; gap: 0.5rem; padding: 0.45rem 0.6rem; border-radius: 10px;
 background: rgba(var(--grc-surface-raised), 0.6); border: 1px solid rgb(var(--grc-border)); font-size: 0.78rem; }
.grc-driver__label { color: rgb(var(--grc-text-muted)); }
.grc-driver__val { font-weight: 700; }

/* Insight 6-part sections */
.grc-inssec { display: flex; flex-direction: column; gap: 0.2rem; }
.grc-inssec__label { font-size: 0.64rem; font-weight: 800; letter-spacing: 0.5px; color: rgb(var(--grc-ai)); }
.grc-inssec__text { font-size: 0.8rem; color: rgb(var(--grc-text)); margin: 0; line-height: 1.45; }
.grc-recactions { margin: 0.2rem 0 0; padding-left: 1.1rem; display: flex; flex-direction: column; gap: 0.3rem; font-size: 0.8rem; color: rgb(var(--grc-text)); }

/* Clickable related chip */
.grc-chip--btn { cursor: pointer; color: rgb(var(--grc-text)); font-family: inherit; }
.grc-chip--btn:hover { border-color: rgba(var(--grc-primary), 0.6); background: rgba(var(--grc-primary), 0.12); }

/* Hero posture contributors + data-quality chip */
.grc-dq-chip { display: inline-flex; }
.grc-hero__contrib { display: flex; flex-direction: column; gap: 0.4rem; margin-top: 0.7rem; padding-top: 0.6rem; border-top: 1px dashed rgb(var(--grc-border)); }
.grc-hero__contrib-row { display: flex; flex-wrap: wrap; gap: 0.5rem 1rem; font-size: 0.76rem; }
.grc-contrib { display: inline-flex; align-items: center; gap: 0.3rem; }
.grc-contrib--up { color: rgb(var(--grc-healthy)); }
.grc-contrib--down { color: rgb(var(--grc-critical)); }
.grc-hero__weights { display: flex; flex-wrap: wrap; gap: 0.35rem; }
.grc-weightpill { font-size: 0.68rem; padding: 0.15rem 0.45rem; border-radius: 8px; background: rgba(var(--grc-surface-raised), 0.8); border: 1px solid rgb(var(--grc-border)); color: rgb(var(--grc-text-muted)); }

/* BU strength/weakness + priority score badge */
.grc-bu-sw { display: flex; flex-direction: column; gap: 2px; font-size: 0.72rem; }
.grc-bu-sw__up { color: rgb(var(--grc-healthy)); }
.grc-bu-sw__down { color: rgb(var(--grc-critical)); }
.grc-score-badge { font-size: 0.64rem; font-weight: 700; padding: 0.1rem 0.4rem; border-radius: 999px; background: rgba(var(--grc-surface-raised), 0.9); border: 1px solid rgb(var(--grc-border)); color: rgb(var(--grc-text-muted)); }
","/* =====================================================================
 Overrides (imported last): left sidebar nav + AI panel/FAB fixes
 ===================================================================== */

/* ---- Primary tabs moved to a left vertical sidebar ---- */
.grc-tabs--side {
 flex-direction: column;
 gap: 0.2rem;
 width: 216px;
 flex-shrink: 0;
 padding: 0.7rem 0.55rem;
 border-bottom: none;
 border-right: 1px solid rgb(var(--grc-border));
 overflow-x: visible;
 overflow-y: auto;
 top: 90px;
 height: calc(100vh - 90px);
 align-self: flex-start;
}
.grc-tabs--side .grc-tab {
 width: 100%;
 justify-content: flex-start;
 padding: 0.6rem 0.7rem;
 border-bottom: none;
 border-left: 2px solid transparent;
 border-radius: 10px;
}
.grc-tabs--side .grc-tab:hover { background: rgba(var(--grc-surface-raised), 0.7); }
.grc-tabs--side .grc-tab--active {
 background: rgba(var(--grc-primary), 0.12);
 border-bottom-color: transparent;
 border-left-color: rgb(var(--grc-primary));
}
.grc-theme-dark .grc-tabs--side .grc-tab--active {
 border-bottom-color: transparent;
 border-left-color: rgb(var(--grc-ai));
 text-shadow: 0 0 14px rgba(var(--grc-ai), 0.5);
}
.grc-tab__label { white-space: nowrap; }

/* ---- AI side panel: keep bottom content above the floating assistant ---- */
.grc-aipanel__body { padding-bottom: 78px; }

/* ---- Floating AI: shift clear of the open AI side panel ---- */
.grc-fab--panel { right: calc(340px + 1.4rem); }
.grc-chatwin--panel { right: calc(340px + 1.4rem); }

/* ---- Insight accent fallbacks for all severities ---- */
.grc-insight--healthy { border-left: 3px solid rgb(var(--grc-healthy)); }
.grc-insight--neutral { border-left: 3px solid rgb(var(--grc-text-faint)); }

/* ---- Responsive: collapse sidebar to an icon rail (AI panel already hides) ---- */
@media (max-width: 1100px) {
 .grc-tabs--side { width: 60px; padding: 0.6rem 0.3rem; }
 .grc-tabs--side .grc-tab { justify-content: center; padding: 0.6rem; }
 .grc-tab__label { display: none; }
 .grc-fab--panel, .grc-chatwin--panel { right: 1.2rem; }
}

/* =====================================================================
 Premium left sidebar (replaces TabNav) + simplified header title
 ===================================================================== */
.grc-sidebar {
 position: sticky; top: 56px; align-self: flex-start; height: calc(100vh - 56px);
 width: 230px; flex-shrink: 0; display: flex; flex-direction: column;
 border-right: 1px solid rgb(var(--grc-border));
 background: linear-gradient(180deg, rgba(var(--grc-surface), 0.96), rgba(var(--grc-surface-2), 0.92));
 overflow-x: hidden; overflow-y: auto; transition: width 160ms ease;
}
.grc-sidebar--collapsed { width: 68px; }

.grc-sidebar__brand { display: flex; align-items: center; gap: 0.55rem; padding: 0.85rem 0.8rem; border-bottom: 1px solid rgb(var(--grc-border)); }
.grc-sidebar--collapsed .grc-sidebar__brand { justify-content: center; padding: 0.85rem 0.4rem; }

.grc-sidebar__nav { display: flex; flex-direction: column; gap: 0.15rem; padding: 0.6rem 0.5rem; flex: 1; }

.grc-navitem {
 display: flex; align-items: center; gap: 0.6rem; width: 100%; cursor: pointer;
 padding: 0.6rem 0.7rem; border: none; background: transparent; border-radius: 10px;
 border-left: 2px solid transparent; color: rgb(var(--grc-text-muted));
 font-size: 0.84rem; font-weight: 600; white-space: nowrap; position: relative;
}
.grc-sidebar--collapsed .grc-navitem { justify-content: center; padding: 0.6rem; }
.grc-navitem:hover { background: rgba(var(--grc-surface-raised), 0.75); color: rgb(var(--grc-text)); }
.grc-navitem--active { background: rgba(var(--grc-primary), 0.12); color: rgb(var(--grc-text)); border-left-color: rgb(var(--grc-primary)); }
.grc-theme-dark .grc-navitem--active { border-left-color: rgb(var(--grc-ai)); box-shadow: inset 2px 0 14px -8px rgba(var(--grc-ai), 0.8); text-shadow: 0 0 12px rgba(var(--grc-ai), 0.4); }
.grc-navitem__label { flex: 1; text-align: left; }
.grc-navitem__badge {
 min-width: 18px; height: 18px; padding: 0 5px; border-radius: 999px; font-size: 0.62rem; font-weight: 800;
 display: grid; place-items: center; background: rgb(var(--grc-critical)); color: #fff;
}
.grc-sidebar--collapsed .grc-navitem__badge { position: absolute; top: 2px; right: 4px; }

.grc-subnav { display: flex; flex-direction: column; gap: 0.1rem; margin: 0.1rem 0 0.3rem; padding-left: 0.4rem; border-left: 1px dashed rgb(var(--grc-border)); margin-left: 0.9rem; }
.grc-subnav--collapsed { margin-left: 0; padding-left: 0; border-left: none; align-items: center; }
.grc-subnav__item {
 display: flex; align-items: center; gap: 0.5rem; width: 100%; cursor: pointer; text-align: left;
 padding: 0.4rem 0.6rem; border: none; background: transparent; border-radius: 8px;
 color: rgb(var(--grc-text-faint)); font-size: 0.78rem; white-space: nowrap;
}
.grc-subnav--collapsed .grc-subnav__item { justify-content: center; padding: 0.4rem; width: auto; }
.grc-subnav__item:hover { background: rgba(var(--grc-surface-raised), 0.7); color: rgb(var(--grc-text)); }
.grc-subnav__item--active { color: rgb(var(--grc-primary)); font-weight: 700; background: rgba(var(--grc-primary), 0.1); }

.grc-sidebar__bottom { display: flex; flex-direction: column; gap: 0.15rem; padding: 0.5rem; border-top: 1px solid rgb(var(--grc-border)); }
.grc-sidebar__ctl {
 display: flex; align-items: center; gap: 0.55rem; width: 100%; cursor: pointer; text-align: left;
 padding: 0.5rem 0.6rem; border: none; background: transparent; border-radius: 9px;
 color: rgb(var(--grc-text-muted)); font-size: 0.8rem; white-space: nowrap;
}
.grc-sidebar--collapsed .grc-sidebar__ctl { justify-content: center; padding: 0.5rem; }
.grc-sidebar__ctl:hover { background: rgba(var(--grc-surface-raised), 0.75); color: rgb(var(--grc-text)); }
.grc-sidebar__user { display: flex; align-items: center; gap: 0.5rem; padding: 0.4rem 0.5rem; }
.grc-sidebar--collapsed .grc-sidebar__user { justify-content: center; }
.grc-sidebar__username { font-size: 0.76rem; font-weight: 600; color: rgb(var(--grc-text-muted)); }
.grc-sidebar__toggle {
 display: flex; align-items: center; justify-content: center; cursor: pointer; margin: 0.3rem 0.5rem 0.6rem;
 padding: 0.35rem; border: 1px solid rgb(var(--grc-border)); background: rgba(var(--grc-surface-raised), 0.7);
 border-radius: 9px; color: rgb(var(--grc-text-muted));
}
.grc-sidebar__toggle:hover { color: rgb(var(--grc-text)); border-color: rgba(var(--grc-primary), 0.6); }

/* Simplified header title block */
.grc-header__title { display: flex; flex-direction: column; line-height: 1.15; flex-shrink: 0; }
.grc-header__crumb { font-size: 0.66rem; color: rgb(var(--grc-text-faint)); letter-spacing: 0.2px; }
.grc-header__page { font-weight: 800; font-size: 1rem; }

/* Keep AI panel aligned to the simplified header height */
.grc-aipanel { top: 56px; height: calc(100vh - 56px); }

@media (max-width: 1024px) {
 .grc-header__title .grc-header__crumb { display: none; }
}
","/* =====================================================================
 Enterprise Risk Intelligence page styles (imported after overrides.css)
 ===================================================================== */

.grc-risk-toolbar { display: flex; justify-content: flex-end; }
.grc-three { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem; align-items: start; }
.grc-row--click { cursor: pointer; }
.grc-up { color: rgb(var(--grc-critical)); font-style: normal; }
.grc-down { color: rgb(var(--grc-healthy)); font-style: normal; }

/* Hero risk metrics */
.grc-riskmetrics { display: grid; grid-template-columns: repeat(3, auto); gap: 0.25rem 0.9rem; font-size: 0.74rem; color: rgb(var(--grc-text-muted)); }
.grc-riskmetrics b { color: rgb(var(--grc-text)); font-size: 0.84rem; }

/* Chip selectors as toggle buttons */
.grc-chip--btn.is-active { background: rgb(var(--grc-primary)); color: #fff; border-color: rgb(var(--grc-primary)); }
.grc-chip__type { font-size: 0.6rem; text-transform: uppercase; letter-spacing: 0.3px; color: rgb(var(--grc-text-faint)); }

/* Category cards */
.grc-catgrid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }
.grc-catcard { display: flex; flex-direction: column; gap: 0.5rem; }
.grc-catcard__head { display: flex; align-items: center; justify-content: space-between; gap: 0.4rem; }
.grc-catcard__name { font-weight: 700; font-size: 0.88rem; display: flex; align-items: center; gap: 0.4rem; }
.grc-catcard__score { font-weight: 800; font-size: 1.3rem; }
.grc-catcard__meta { display: flex; flex-wrap: wrap; gap: 0.35rem; }
.grc-catcard__stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 0.25rem 0.5rem; font-size: 0.7rem; color: rgb(var(--grc-text-muted)); }
.grc-catcard__foot { display: flex; flex-wrap: wrap; gap: 0.6rem; }
.grc-why { background: none; border: none; cursor: pointer; color: rgb(var(--grc-primary)); font-size: 0.72rem; display: inline-flex; align-items: center; gap: 0.3rem; padding: 0; }
.grc-why:hover { text-decoration: underline; }

/* Threshold bar overlay (appetite/tolerance ticks over a MiniBar) */
.grc-thresh { position: relative; }
.grc-thresh__tick { position: absolute; top: -3px; width: 2px; height: 14px; background: rgb(var(--grc-watch)); transform: translateX(-1px); border-radius: 2px; }
.grc-thresh__tick--c { background: rgb(var(--grc-critical)); }

/* Aggregation breakdown box */
.grc-aggbox { border: 1px dashed rgb(var(--grc-border)); border-radius: 10px; padding: 0.6rem; display: flex; flex-direction: column; gap: 0.3rem; background: rgba(var(--grc-surface-raised), 0.4); }
.grc-aggbox__title { font-size: 0.68rem; font-weight: 800; text-transform: uppercase; letter-spacing: 0.3px; color: rgb(var(--grc-text-muted)); margin-top: 0.2rem; }
.grc-aggrow { display: grid; grid-template-columns: 1.3fr 1fr auto; gap: 0.5rem; align-items: center; font-size: 0.74rem; }
.grc-aggrow__label em { color: rgb(var(--grc-text-faint)); font-style: normal; font-size: 0.66rem; }
.grc-aggrow__nums { grid-column: 2 / -1; color: rgb(var(--grc-text-muted)); font-size: 0.7rem; }

/* Appetite monitor */
.grc-bullet { display: flex; flex-direction: column; gap: 0.35rem; padding: 0.55rem 0; border-bottom: 1px dashed rgb(var(--grc-border)); }
.grc-bullet:last-child { border-bottom: none; }
.grc-bullet__top { display: flex; align-items: center; justify-content: space-between; gap: 0.5rem; }
.grc-bullet__name { font-weight: 700; font-size: 0.84rem; }
.grc-bullet__meta { display: flex; flex-wrap: wrap; gap: 0.4rem 0.9rem; font-size: 0.74rem; color: rgb(var(--grc-text-muted)); align-items: center; }
.grc-bullet__breach { display: inline-flex; align-items: center; gap: 0.3rem; }

/* Appetite inheritance layers */
.grc-layer { padding: 0.5rem 0.6rem; border-radius: 10px; border: 1px solid rgb(var(--grc-border)); margin-bottom: 0.4rem; background: rgba(var(--grc-surface-raised), 0.5); }
.grc-layer--override { border-color: rgba(var(--grc-watch), 0.6); background: rgba(var(--grc-watch), 0.08); }
.grc-layer__top { display: flex; align-items: center; gap: 0.5rem; flex-wrap: wrap; }
.grc-layer__level { font-size: 0.6rem; text-transform: uppercase; letter-spacing: 0.3px; color: rgb(var(--grc-text-faint)); min-width: 92px; }
.grc-layer__name { font-weight: 700; font-size: 0.8rem; flex: 1; }
.grc-layer__vals { font-weight: 700; font-size: 0.78rem; }
.grc-layer__ovr { display: flex; flex-wrap: wrap; align-items: center; gap: 0.4rem; margin-top: 0.3rem; font-size: 0.72rem; color: rgb(var(--grc-text-muted)); }
.grc-layer__ovr em { flex-basis: 100%; font-style: normal; color: rgb(var(--grc-text-muted)); }
.grc-layer__inh { font-size: 0.7rem; color: rgb(var(--grc-text-faint)); display: inline-flex; align-items: center; gap: 0.25rem; }

/* KRI totals */
.grc-kritotals { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }

/* Hierarchy tree */
.grc-tree { display: flex; flex-direction: column; max-height: 520px; overflow-y: auto; }
.grc-tree__row { display: flex; align-items: center; gap: 0.4rem; padding: 0.4rem 0.6rem; border-bottom: 1px solid rgb(var(--grc-border)); cursor: pointer; font-size: 0.78rem; }
.grc-tree__row:hover { background: rgba(var(--grc-primary), 0.06); }
.grc-tree__row--sel { background: rgba(var(--grc-primary), 0.12); }
.grc-tree__caret { background: none; border: none; cursor: pointer; color: rgb(var(--grc-text-muted)); padding: 0; display: inline-flex; }
.grc-tree__name { font-weight: 600; flex: 1; }
.grc-tree__level { font-size: 0.6rem; text-transform: uppercase; color: rgb(var(--grc-text-faint)); width: 72px; }
.grc-tree__owner { font-size: 0.7rem; color: rgb(var(--grc-text-muted)); width: 110px; }
.grc-tree__score { font-weight: 800; width: 72px; text-align: right; }
.grc-tree__score em { font-weight: 600; font-size: 0.66rem; color: rgb(var(--grc-text-faint)); }
.grc-tree__links { display: flex; gap: 0.5rem; font-size: 0.68rem; color: rgb(var(--grc-text-muted)); }
.grc-tree__links span { display: inline-flex; align-items: center; gap: 0.15rem; }

/* Weighting panel */
.grc-weightpanel { display: flex; flex-direction: column; gap: 0.4rem; }
.grc-weightrow { display: flex; flex-direction: column; gap: 0.2rem; padding: 0.5rem; border-radius: 10px; background: rgba(var(--grc-surface-raised), 0.5); border: 1px solid rgb(var(--grc-border)); }
.grc-weightrow__name { font-weight: 700; font-size: 0.8rem; }
.grc-weightrow__nums { font-size: 0.72rem; color: rgb(var(--grc-text-muted)); }
.grc-weightrow__w { font-size: 0.74rem; }
.grc-weightrow__btns { display: flex; flex-wrap: wrap; gap: 0.3rem; margin-top: 0.2rem; }

/* Driver analysis */
.grc-driverbtn { display: grid; grid-template-columns: 1.2fr 1fr auto; gap: 0.5rem; align-items: center; width: 100%; text-align: left; cursor: pointer;
 background: transparent; border: 1px solid transparent; border-radius: 9px; padding: 0.4rem 0.5rem; font-size: 0.76rem; color: rgb(var(--grc-text)); margin-bottom: 0.2rem; }
.grc-driverbtn:hover { background: rgba(var(--grc-surface-raised), 0.7); }
.grc-driverbtn.is-active { border-color: rgba(var(--grc-primary), 0.6); background: rgba(var(--grc-primary), 0.1); }
.grc-driverbtn__label { font-weight: 600; }

.grc-callout { display: flex; gap: 0.5rem; align-items: flex-start; font-size: 0.76rem; padding: 0.5rem 0.6rem; border-radius: 10px; margin-top: 0.5rem; }
.grc-callout--high { background: rgba(var(--grc-high), 0.1); border: 1px solid rgba(var(--grc-high), 0.4); }
.grc-callout--critical { background: rgba(var(--grc-critical), 0.1); border: 1px solid rgba(var(--grc-critical), 0.4); }

/* Control + mitigation rows */
.grc-ctrlrow { display: grid; grid-template-columns: 1.4fr 1fr auto auto; gap: 0.5rem; align-items: center; font-size: 0.74rem; padding: 0.3rem 0; }
.grc-ctrlrow__name em { color: rgb(var(--grc-text-faint)); font-style: normal; }
.grc-ctrlrow__red { color: rgb(var(--grc-healthy)); font-weight: 700; }
.grc-ctrlrow__wif { color: rgb(var(--grc-critical)); display: inline-flex; align-items: center; gap: 0.2rem; }
.grc-mitrow { display: grid; grid-template-columns: 1.3fr 1fr auto; gap: 0.5rem; align-items: center; font-size: 0.74rem; padding: 0.3rem 0; }
.grc-mitrow__nums { color: rgb(var(--grc-text-muted)); }

/* Forecast + scenario */
.grc-forecastgrid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 0.6rem; margin-bottom: 0.6rem; }
.grc-lever { display: flex; flex-direction: column; gap: 0.3rem; margin-bottom: 0.6rem; }
.grc-lever__top { display: flex; align-items: center; justify-content: space-between; font-size: 0.78rem; }
.grc-range { width: 100%; accent-color: rgb(var(--grc-primary)); cursor: pointer; }
.grc-whatifout { display: flex; flex-wrap: wrap; gap: 0.8rem 1.2rem; align-items: center; padding: 0.6rem; border-radius: 10px; background: rgba(var(--grc-surface-raised), 0.5); border: 1px solid rgb(var(--grc-border)); margin-bottom: 0.5rem; }

/* Emerging + recommendations */
.grc-emerging, .grc-rec { display: flex; flex-direction: column; gap: 0.5rem; }
.grc-rec__meta { display: flex; flex-wrap: wrap; gap: 0.4rem 0.9rem; font-size: 0.72rem; color: rgb(var(--grc-text-muted)); align-items: center; }

/* Connection graph */
.grc-graph__count { font-size: 13px; font-weight: 800; fill: rgb(var(--grc-text)); }
.grc-graph__center { font-size: 12px; font-weight: 800; fill: rgb(var(--grc-text)); }

/* Trend events */
.grc-eventlegend { display: flex; flex-wrap: wrap; gap: 0.5rem 1rem; font-size: 0.72rem; color: rgb(var(--grc-text-muted)); margin-top: 0.4rem; }
.grc-eventlegend span { display: inline-flex; align-items: center; gap: 0.3rem; }

/* Briefing mode */
.grc-brief-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 1rem; }
.grc-briefrow { display: flex; align-items: center; justify-content: space-between; gap: 0.5rem; font-size: 0.78rem; padding: 0.3rem 0; border-bottom: 1px dashed rgb(var(--grc-border)); }
.grc-briefrow:last-child { border-bottom: none; }

@media (max-width: 1440px) {
 .grc-catgrid { grid-template-columns: repeat(3, 1fr); }
 .grc-three { grid-template-columns: 1fr; }
 .grc-brief-grid { grid-template-columns: repeat(2, 1fr); }
}
@media (max-width: 1100px) {
 .grc-catgrid, .grc-kritotals, .grc-forecastgrid { grid-template-columns: repeat(2, 1fr); }
 .grc-brief-grid { grid-template-columns: 1fr; }
}
@media (max-width: 720px) {
 .grc-catgrid, .grc-kritotals { grid-template-columns: 1fr; }
}
