","import React, { useState, useRef, useEffect } from "react";
import { Icon } from "@servicenow/react-components/Icon";

// Compact popover menu (navigation/scope selector — not a form field).
export function Dropdown({ label, value, options, onChange, icon }: {
 label?: string;
 value: string;
 options: string[];
 onChange: (v: string) => void;
 icon?: string;
}) {
 const [open, setOpen] = useState(false);
 const ref = useRef<HTMLDivElement>(null);

 useEffect(() => {
 const onDoc = (e: MouseEvent) => {
 if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
 };
 document.addEventListener("mousedown", onDoc);
 return () => document.removeEventListener("mousedown", onDoc);
 }, []);

 return (
 <div className="grc-sel" ref={ref} style={{ position: "relative" }}>
 {label ? <span className="grc-sel__label">{label}</span> : null}
 <button className="grc-sel__control" onClick={() => setOpen(o => !o)} aria-haspopup="listbox" aria-expanded={open}>
 {icon ? <Icon icon={icon as any} size="sm" /> : null}
 <span>{value}</span>
 <Icon icon="caret-down-outline" size="sm" />
 </button>
 {open ? (
 <div className="grc-menu" role="listbox">
 {options.map(opt => (
 <button
 key={opt}
 role="option"
 aria-selected={opt === value}
 className={`grc-menu__item ${opt === value ? "is-active" : ""}`}
 onClick={() => { onChange(opt); setOpen(false); }}
 >
 {opt === value ? <Icon icon="check-outline" size="sm" /> : <span style={{ width: 16 }} />}
 <span>{opt}</span>
 </button>
 ))}
 </div>
 ) : null}
 </div>
 );
}
","// Central mock data layer for the GRC VP Command Center.
// Realistic executive mock data only. No backend logic.

export type Severity = "critical" | "high" | "watch" | "info" | "healthy" | "neutral";
export type AppetiteStatus = "within" | "approaching" | "above" | "breach";

export interface GlobalSelectors {
 entity: string;
 businessUnit: string;
 riskCategory: string;
 period: string;
 scenario: string;
}

export const SELECTOR_OPTIONS = {
 entity: ["Saudi Energy Group", "SE Downstream Co.", "SE Power & Utilities", "SE Trading Ltd."],
 businessUnit: ["All Business Units", "Finance", "Operations", "Procurement", "Technology", "HR", "Corporate"],
 riskCategory: ["All Categories", "Operational", "Financial", "Regulatory", "Cyber", "Strategic", "Supply Chain", "People", "Third-Party"],
 period: ["Last 30 Days", "Last 90 Days", "Last 6 Months", "Last 12 Months", "YTD"],
 scenario: ["Current Posture", "Stress Scenario", "Target State", "Board Projection"]
};

export const DEFAULT_SELECTORS: GlobalSelectors = {
 entity: "Saudi Energy Group",
 businessUnit: "All Business Units",
 riskCategory: "All Categories",
 period: "Last 90 Days",
 scenario: "Current Posture"
};

