","import React, { createContext, useContext, useState, useCallback } from "react";
import { Modal } from "@servicenow/react-components/Modal";

interface ActionReq { title: string; message: string; }
interface ActionsCtx { run: (title: string, message?: string) => void; }

const ActionsContext = createContext<ActionsCtx>({ run: () => {} });

export function ActionsProvider({ children }: { children: React.ReactNode }) {
 const [req, setReq] = useState<ActionReq | null>(null);

 const run = useCallback((title: string, message?: string) => {
 setReq({ title, message: message || `This is a mock action. In a later phase, "${title}" will connect to real GRC workflows, data, and AI services.` });
 }, []);

 const close = useCallback(() => setReq(null), []);

 return (
 <ActionsContext.Provider value={{ run }}>
 {children}
 {req ? (
 <Modal
 opened
 size="sm"
 headerLabel={req.title}
 content={req.message}
