// Lookup with a model-derived fallback so every KPI returns a usable insight.
export function getInsightForKpi(kpiId: string): ExecutiveInsight {
 const hit = INSIGHTS[kpiId];
 if (hit) return hit;
 const k = getKpi(kpiId);
 const name = k ? k.name : kpiId;
 const val = k ? formatKpiValue(k) : "—";
 const dir = k && k.trendDir === "up" ? "rose" : k && k.trendDir === "down" ? "eased" : "held steady";
 return {
 kpiRef: kpiId,
 signal: `${name} is at ${val} and ${dir} ${k ? Math.abs(k.trendPct) : 0}% over the period.`,
 impact: k ? `${name} affects the ${k.domain} domain against a target of ${k.target}${k.unit === "%" ? "%" : ""}.` : "Impact under assessment.",
 cause: k ? k.whatItMeans || "Drivers are under review." : "Drivers are under review.",
 prediction: k ? `Forecast suggests ${name} continues trending ${k.trendDir} without intervention.` : "Trend forecast pending.",
 recommendation: k ? `Monitor ${name} against its ${k.target} target and act if it crosses the warning threshold.` : "Monitor and reassess.",
 action: k ? `Open the ${k.domain} workspace for detail.` : "Open the related workspace.",
 recommendedActions: [
 `Review the primary drivers behind ${name}.`,
 `Assign an owner to close the gap to target.`,
 `Set a review checkpoint for the next reporting cycle.`
 ]
 };
}
