","// 5-level risk hierarchy: Enterprise → Category → Business Unit → Process → Individual Risk.
// Each node carries a score, owners, trend, weight (share of parent), and linkage counts.
// Parent score = Σ(childWeight × childScore) — roll-up / propagation.

export type NodeLevel = "enterprise" | "category" | "bu" | "process" | "risk";

export interface HierNode {
 id: string;
 name: string;
 level: NodeLevel;
 score: number;
 owner: string;
 businessOwner: string;
 trend: "up" | "down" | "flat";
 weight: number; // share of parent (0-1)
 controls: number;
 kris: number;
 mitigations: number;
 // AI weight recommendation (human-reviewed, never auto-applied).
 aiSuggestedWeight?: number;
 weightRationale?: string;
 children?: HierNode[];
}

const leaf = (id: string, name: string, score: number, owner: string, weight: number, c: number, k: number, m: number, trend: HierNode["trend"], ai?: number, rationale?: string): HierNode =>
 ({ id, name, level: "risk", score, owner, businessOwner: owner, trend, weight, controls: c, kris: k, mitigations: m, aiSuggestedWeight: ai, weightRationale: rationale });

// Operational example chain (Plant Failure 88 w30%, Supplier Disruption 79 w25%,
// Workforce 73 w20%, Technology Outage 84 w25%).
const operationalProcess: HierNode = {
 id: "proc-plant-ops", name: "Plant Operations", level: "process", score: 82.1, owner: "Plant Director",
 businessOwner: "COO", trend: "up", weight: 0.55, controls: 7, kris: 3, mitigations: 5,
 children: [
 leaf("risk-plant-failure", "Plant Failure", 88, "Reliability Lead", 0.30, 4, 2, 2, "up"),
 leaf("risk-supplier-disruption", "Supplier Disruption", 79, "Procurement Lead", 0.25, 3, 1, 2, "up", 0.31,
 "KRI acceleration (+19%) and supplier concentration suggest Supplier Disruption contributes more to Operational residual than its current 25% weight."),
 leaf("risk-workforce", "Workforce Availability", 73, "HR Ops Lead", 0.20, 2, 1, 1, "flat"),
 leaf("risk-tech-outage", "Technology Outage", 84, "IT Ops Lead", 0.25, 3, 1, 1, "up")
 ]
};

const operationalCategory: HierNode = {
 id: "cat-operational", name: "Operational", level: "category", score: 82.1, owner: "COO Risk",
 businessOwner: "COO", trend: "up", weight: 0.22, controls: 12, kris: 5, mitigations: 9,
 children: [
 { id: "bu-operations", name: "Operations BU", level: "bu", score: 82.1, owner: "VP Operations",
 businessOwner: "COO", trend: "up", weight: 0.6, controls: 9, kris: 4, mitigations: 7,
 children: [operationalProcess] },
 { id: "bu-procurement-op", name: "Procurement BU", level: "bu", score: 76.4, owner: "VP Procurement",
 businessOwner: "CPO", trend: "up", weight: 0.4, controls: 3, kris: 1, mitigations: 2,
 children: [leaf("risk-logistics", "Logistics Breakdown", 76.4, "Logistics Lead", 1, 3, 1, 2, "up")] }
 ]
};

const simpleCat = (id: string, name: string, score: number, weight: number, c: number, k: number, m: number, trend: HierNode["trend"]): HierNode => ({
 id: `cat-${id}`, name, level: "category", score, owner: "COO Risk", businessOwner: "Exec Sponsor",
 trend, weight, controls: c, kris: k, mitigations: m,
 children: [leaf(`risk-${id}`, `${name} Primary Risk`, score, "Category Lead", 1, c, k, m, trend)]
});

export const RISK_TREE: HierNode = {
 id: "enterprise", name: "Enterprise Risk", level: "enterprise", score: 72.4, owner: "Chief Risk Officer",
 businessOwner: "CEO", trend: "up", weight: 1, controls: 500, kris: 84, mitigations: 71,
 children: [
 operationalCategory,
 simpleCat("supply", "Supply Chain", 78.8, 0.16, 8, 2, 6, "up"),
 simpleCat("regulatory", "Regulatory", 74.6, 0.14, 37, 1, 5, "up"),
 simpleCat("cyber", "Cyber", 68.3, 0.14, 24, 1, 4, "flat"),
 simpleCat("thirdparty", "Third-Party", 65.9, 0.10, 11, 1, 4, "up"),
 simpleCat("financial", "Financial", 61.7, 0.12, 46, 1, 3, "down"),
 simpleCat("strategic", "Strategic", 57.4, 0.07, 9, 0, 2, "flat"),
 simpleCat("people", "People", 49.6, 0.05, 15, 0, 2, "down")
 ]
};

// Weighted roll-up of a node's children (propagation check).
export function rollUp(node: HierNode): number {
 if (!node.children || !node.children.length) return node.score;
 return +node.children.reduce((a, c) => a + c.weight * rollUp(c), 0).toFixed(1);
}

export function findNode(id: string, node: HierNode = RISK_TREE): HierNode | undefined {
 if (node.id === id) return node;
 for (const c of node.children || []) {
 const hit = findNode(id, c);
 if (hit) return hit;
 }
 return undefined;
}
","// Semi-qualitative risk aggregation. Configurable component weights sum to 100.
import { RiskCategory, Velocity } from "../data/risk/categories";
import { findNode, HierNode } from "../data/risk/hierarchy";

export interface AggWeights {
 residualRisk: number;
 appetiteVariance: number;
 velocity: number;
 financialExposure: number;
 controlWeakness: number;
 kriSeverity: number;
}

export const AGG_WEIGHTS: AggWeights = {
 residualRisk: 40,
 appetiteVariance: 20,
 velocity: 15,
 financialExposure: 10,
 controlWeakness: 10,
 kriSeverity: 5
};

const VELOCITY_INPUT: Record<Velocity, number> = { slow: 0.25, moderate: 0.5, fast: 0.75, rapid: 1 };
const MAX_EXPOSURE = 100;
const MAX_KRIS = 6;

export interface AggComponent {
 key: keyof AggWeights;
 label: string;
 weight: number;
 inputPct: number; // 0-100 normalized input
 contribution: number; // points toward the final score
}

export interface ChildContribution {
 id: string;
 name: string;
 weight: number;
 scoreContribution: number;
 trendContribution: number;
 controlImpact: number;
}

export interface AggResult {
 score: number;
 rawScore: number;
 components: AggComponent[];
 topChildren: ChildContribution[];
}

function componentInputs(c: RiskCategory): Record<keyof AggWeights, number> {
 const apptSpan = Math.max(1, c.tolerance - c.appetite);
 return {
 residualRisk: Math.max(0, Math.min(1, c.residualScore / 100)),
 appetiteVariance: Math.max(0, Math.min(1, (c.currentScore - c.appetite) / apptSpan + 0.5)),
 velocity: VELOCITY_INPUT[c.velocity],
 financialExposure: Math.max(0, Math.min(1, c.financialExposure / MAX_EXPOSURE)),
 controlWeakness: Math.max(0, Math.min(1, (100 - c.controlEffectiveness) / 100)),
 kriSeverity: Math.max(0, Math.min(1, c.triggeredKRIs / MAX_KRIS))
 };
}

const LABELS: Record<keyof AggWeights, string> = {
 residualRisk: "Residual Risk",
 appetiteVariance: "Appetite Variance",
 velocity: "Velocity",
 financialExposure: "Financial Exposure",
 controlWeakness: "Control Weakness",
 kriSeverity: "KRI Severity"
};

// Aggregate a category: breakdown is scaled so contributions sum to currentScore.
export function aggregate(c: RiskCategory, weights: AggWeights = AGG_WEIGHTS): AggResult {
 const inputs = componentInputs(c);
 const keys = Object.keys(weights) as (keyof AggWeights)[];
 const raw = keys.map(k => ({ key: k, weighted: (weights[k] / 100) * inputs[k] * 100 }));
 const rawScore = raw.reduce((a, r) => a + r.weighted, 0);
 const scale = rawScore > 0 ? c.currentScore / rawScore : 1;
 const components: AggComponent[] = raw.map(r => ({
 key: r.key,
 label: LABELS[r.key],
 weight: weights[r.key],
 inputPct: Math.round(inputs[r.key] * 100),
 contribution: +(r.weighted * scale).toFixed(1)
 }));
 return { score: c.currentScore, rawScore: +rawScore.toFixed(1), components, topChildren: childContributions(c) };
}

// Top contributing child risks (from the hierarchy where modelled).
export function childContributions(c: RiskCategory): ChildContribution[] {
 const node = findNode(`cat-${c.id}`);
 const kids: HierNode[] = [];
 const collect = (n?: HierNode) => {
 (n?.children || []).forEach(ch => { if (ch.level === "risk") kids.push(ch); else collect(ch); });
 };
 collect(node);
 return kids
 .map(k => ({
 id: k.id,
 name: k.name,
 weight: k.weight,
 scoreContribution: +(k.weight * k.score).toFixed(1),
 trendContribution: k.trend === "up" ? +(k.weight * 6).toFixed(1) : k.trend === "down" ? -+(k.weight * 3).toFixed(1) : 0,
 controlImpact: +((1 - k.weight) * 2).toFixed(1)
 }))
 .sort((a, b) => b.scoreContribution - a.scoreContribution)
 .slice(0, 4);
}
","// Multi-layer risk appetite with inheritance + override metadata.
export type ApprovalStatus = "Approved" | "Pending" | "Draft";

export interface AppetiteLayer {
 id: string;
 level: "Enterprise" | "Category" | "Business Unit" | "Entity" | "Process";
 name: string;
 appetite: number;
 tolerance: number;
 inherited: boolean;
 override?: {
 changedBy: string;
 reason: string;
 effectiveDate: string;
 approvalStatus: ApprovalStatus;
 };
}

// Example inheritance chain: Enterprise Operational 85 → Operations BU 82 (override)
// → Plant Operations 80 (override).
export const OPERATIONAL_APPETITE_CHAIN: AppetiteLayer[] = [
 { id: "ent-op", level: "Enterprise", name: "Enterprise Operational", appetite: 85, tolerance: 92, inherited: false },
 { id: "cat-op", level: "Category", name: "Operational Category", appetite: 85, tolerance: 92, inherited: true },
 {
 id: "bu-op", level: "Business Unit", name: "Operations BU", appetite: 82, tolerance: 90, inherited: false,
 override: { changedBy: "VP Operations", reason: "Elevated continuity risk during peak demand season warrants a tighter operating boundary.", effectiveDate: "2024-09-01", approvalStatus: "Approved" }
 },
 { id: "ent-plantco", level: "Entity", name: "SE Power & Utilities", appetite: 82, tolerance: 90, inherited: true },
 {
 id: "proc-plant", level: "Process", name: "Plant Operations", appetite: 80, tolerance: 88, inherited: false,
 override: { changedBy: "Plant Director", reason: "Ageing asset base and deferred maintenance require the strictest tolerance in the group.", effectiveDate: "2024-09-18", approvalStatus: "Pending" }
 }
];

export interface AppetiteMonitorRow {
 category: string;
 current: number;
 appetite: number;
 tolerance: number;
 headroom: number;
 trendPct: number;
 predictedBreach: string;
}

import { RISK_CATEGORIES } from "./categories";

export const APPETITE_MONITOR: AppetiteMonitorRow[] = RISK_CATEGORIES.map(c => ({
 category: c.name,
 current: c.currentScore,
 appetite: c.appetite,
 tolerance: c.tolerance,
 headroom: +(c.appetite - c.currentScore).toFixed(1),
 trendPct: c.trendPct,
 predictedBreach:
 c.id === "operational" ? "~21 days" :
 c.id === "supply" ? "~34 days" :
 c.currentScore > c.appetite ? "Breached" :
 c.currentScore > c.appetite - 4 ? "~45 days" : "No near-term breach"
}));

export type AppetiteState = "within" | "approaching" | "outside" | "above-tolerance";

export function appetiteState(current: number, appetite: number, tolerance: number): AppetiteState {
 if (current > tolerance) return "above-tolerance";
 if (current > appetite) return "outside";
 if (current >= appetite - 3) return "approaching";
 return "within";
}

export const APPETITE_STATE_LABEL: Record<AppetiteState, string> = {
 within: "Within Appetite",
 approaching: "Approaching Appetite",
 outside: "Outside Appetite",
 "above-tolerance": "Above Tolerance"
};

export function appetiteStateSeverity(s: AppetiteState): "healthy" | "watch" | "high" | "critical" {
 return s === "within" ? "healthy" : s === "approaching" ? "watch" : s === "outside" ? "high" : "critical";
}
