 <span><Icon icon="chart-trend-outline" size="sm" /> {VELOCITY_LABEL[cat.velocity]} ({cat.velocityPts > 0 ? "+" : ""}{cat.velocityPts}/30d)</span>
 <span>Risks {cat.underlyingRiskCount}</span>
 <span>KRIs {cat.triggeredKRIs}</span>
