 </div>
 <div className="grc-catcard__foot">
 <button className="grc-why" onClick={() => setShowWhy(v => !v)}>
 <Icon icon="circle-question-outline" size="sm" /> Why is this score {cat.currentScore}?
 </button>
 {onOpen ? <button className="grc-why" onClick={() => onOpen(cat.id)}><Icon icon="arrow-up-right-outline" size="sm" /> Drill in</button> : null}
 </div>
 {showWhy ? (
 <div className="grc-aggbox">
 <div className="grc-aggbox__title">Semi-qualitative aggregation (raw {agg.rawScore} → adjusted {cat.currentScore})</div>
 {agg.components.map(c => (
