 <b>{c.contribution}</b>
 </div>
 ))}
 {agg.topChildren.length ? (
 <>
 <div className="grc-aggbox__title">Top contributing risks</div>
 {agg.topChildren.map(ch => (
 <div className="grc-aggrow" key={ch.id}>
 <span className="grc-aggrow__label">{ch.name} <em>· w{Math.round(ch.weight * 100)}%</em></span>
