","import React from "react";
import { Icon } from "@servicenow/react-components/Icon";
import { TrendArrow } from "../viz/Indicators";
import { HierNode, rollUp } from "../../data/risk/hierarchy";

const LEVEL_ICON: Record<string, string> = {
 enterprise: "building-outline", category: "grid-outline", bu: "user-group-outline",
 process: "diagram-next-outline", risk: "chart-bubble-outline"
};

export function TreeNode({ node, depth, expanded, selectedId, onToggle, onSelect }: {
 node: HierNode; depth: number; expanded: Set<string>; selectedId: string | null;
 onToggle: (id: string) => void; onSelect: (node: HierNode) => void;
}) {
 const hasKids = !!(node.children && node.children.length);
 const open = expanded.has(node.id);
 const rolled = hasKids ? rollUp(node) : node.score;
 return (
 <>
 <div
 className={`grc-tree__row ${selectedId === node.id ? "grc-tree__row--sel" : ""}`}
 style={{ paddingLeft: depth * 18 + 8 }}
 onClick={() => onSelect(node)}
 role="button"
 tabIndex={0}
 >
 <button className="grc-tree__caret" onClick={e => { e.stopPropagation(); if (hasKids) onToggle(node.id); }} aria-label={open ? "Collapse" : "Expand"}>
 {hasKids ? <Icon icon={(open ? "chevron-down-outline" : "chevron-right-outline") as any} size="sm" /> : <span style={{ width: 14, display: "inline-block" }} />}
 </button>
 <Icon icon={LEVEL_ICON[node.level] as any} size="sm" />
 <span className="grc-tree__name">{node.name}</span>
 <span className="grc-tree__level">{node.level}</span>
 <span className="grc-tree__owner">{node.owner}</span>
 <span className="grc-tree__score">{node.score}{hasKids ? <em title="weighted roll-up"> ≈{rolled}</em> : null}</span>
 <span className="grc-tree__links">
 <span title="controls"><Icon icon="shield-check-outline" size="sm" />{node.controls}</span>
 <span title="KRIs"><Icon icon="gauge-outline" size="sm" />{node.kris}</span>
 <span title="mitigations"><Icon icon="wrench-outline" size="sm" />{node.mitigations}</span>
 </span>
 <TrendArrow dir={node.trend} />
 </div>
 {hasKids && open ? node.children!.map(c => (
 <TreeNode key={c.id} node={c} depth={depth + 1} expanded={expanded} selectedId={selectedId} onToggle={onToggle} onSelect={onSelect} />
 )) : null}
 </>
 );
}
","import React, { useState } from "react";
import { Button } from "@servicenow/react-components/Button";
import { Icon } from "@servicenow/react-components/Icon";
import { Card, SectionHead, Metric } from "../common/Card";
import { useActions } from "../common/Actions";
import { TreeNode } from "./TreeNode";
import { RISK_TREE, HierNode, rollUp } from "../../data/risk/hierarchy";

function WeightingPanel({ node }: { node: HierNode }) {
 const { run } = useActions();
 const kids = node.children || [];
 if (!kids.length) return null;
 return (
 <div className="grc-weightpanel">
 <div className="grc-aggbox__title">Parent–Child Weighting · {node.name}</div>
 {kids.map(c => {
 const current = Math.round(c.weight * 100);
 const ai = c.aiSuggestedWeight ? Math.round(c.aiSuggestedWeight * 100) : null;
 const variance = ai != null ? ai - current : 0;
 return (
 <div className="grc-weightrow" key={c.id}>
 <span className="grc-weightrow__name">{c.name}</span>
 <span className="grc-weightrow__nums">residual {c.score} · contrib {(c.weight * c.score).toFixed(1)}</span>
 <span className="grc-weightrow__w">current {current}%{ai != null ? <> · AI {ai}% <em className={variance > 0 ? "grc-up" : "grc-down"}>({variance > 0 ? "+" : ""}{variance}%)</em></> : null}</span>
 {c.aiSuggestedWeight ? (
 <span className="grc-weightrow__btns">
 <Button label="Accept Weight" size="sm" variant="primary" onClicked={() => run("Accept AI Weight", `Mock (human-reviewed): adopt AI weight ${ai}% for "${c.name}". ${c.weightRationale}`)} />
 <Button label="Modify" size="sm" variant="secondary" onClicked={() => run("Modify Weight", `Mock: open the weight editor for "${c.name}".`)} />
 <Button label="Dismiss" size="sm" variant="tertiary" onClicked={() => run("Dismiss Suggestion", `Mock: dismiss AI weight suggestion for "${c.name}".`)} />
 <Button label="View Rationale" size="sm" variant="tertiary" onClicked={() => run("AI Rationale", c.weightRationale || "")} />
 </span>
 ) : null}
 </div>
 );
 })}
 </div>
 );
}

export function RiskHierarchy() {
 const [expanded, setExpanded] = useState<Set<string>>(new Set(["enterprise", "cat-operational", "bu-operations"]));
 const [selected, setSelected] = useState<HierNode>(RISK_TREE);
 const toggle = (id: string) => setExpanded(prev => { const n = new Set(prev); n.has(id) ? n.delete(id) : n.add(id); return n; });

 return (
 <section className="grc-section">
 <SectionHead icon="hierarchy-2-outline" title="5-Level Risk Hierarchy" hint="Enterprise → Category → Business Unit → Process → Risk · weighted roll-up & drill-down" />
 <div className="grc-two" style={{ alignItems: "start", gridTemplateColumns: "1.4fr 1fr" }}>
 <Card pad0>
 <div className="grc-tree">
 <TreeNode node={RISK_TREE} depth={0} expanded={expanded} selectedId={selected.id} onToggle={toggle} onSelect={setSelected} />
 </div>
 </Card>
 <Card title={`Node · ${selected.name}`} icon="info-circle-outline">
 <div className="grc-fieldgrid">
 <Metric label="Level" value={selected.level} />
 <Metric label="Score" value={selected.score} />
 <Metric label="Weighted Roll-up" value={rollUp(selected)} />
 <Metric label="Risk Owner" value={selected.owner} />
 <Metric label="Business Owner" value={selected.businessOwner} />
 <Metric label="Weight of Parent" value={`${Math.round(selected.weight * 100)}%`} />
 </div>
 <div className="grc-chips" style={{ margin: "0.5rem 0" }}>
 <span className="grc-chip"><Icon icon="shield-check-outline" size="sm" />{selected.controls} controls</span>
 <span className="grc-chip"><Icon icon="gauge-outline" size="sm" />{selected.kris} KRIs</span>
 <span className="grc-chip"><Icon icon="wrench-outline" size="sm" />{selected.mitigations} mitigations</span>
 </div>
 <WeightingPanel node={selected} />
 </Card>
 </div>
 </section>
 );
}
