","// Scenario analysis — named scenarios + what-if lever definitions.
export interface ScenarioImpact {
 label: string;
 base: number;
 projected: number;
 unit?: string;
}

export interface Scenario {
 id: string;
 name: string;
 description: string;
 impacts: ScenarioImpact[];
 affected: { bus: number; controls: number; policies: number; mitigations: number };
}

export const SCENARIOS: Scenario[] = [
 {
 id: "supplier-failure", name: "Major Supplier Failure",
 description: "A critical single-source supplier fails to deliver for an extended period.",
 impacts: [
 { label: "Operational Risk", base: 82, projected: 91 },
 { label: "Supply Chain Risk", base: 76, projected: 94 },
 { label: "Enterprise GRC", base: 78, projected: 69 },
 { label: "Risks Outside Appetite", base: 7, projected: 13 },
 { label: "Exposure", base: 18.4, projected: 36.7, unit: "SAR M" }
 ],
 affected: { bus: 5, controls: 11, policies: 6, mitigations: 17 }
 },
 { id: "system-outage", name: "Critical System Outage", description: "Extended outage of a core operational technology platform.",
 impacts: [{ label: "Operational Risk", base: 82, projected: 89 }, { label: "Cyber Risk", base: 68, projected: 77 }, { label: "Enterprise GRC", base: 78, projected: 72 }, { label: "Exposure", base: 18.4, projected: 29.1, unit: "SAR M" }],
 affected: { bus: 4, controls: 9, policies: 4, mitigations: 12 } },
 { id: "reg-change", name: "Major Regulatory Change", description: "A sweeping new regulatory obligation lands across Finance and Procurement.",
 impacts: [{ label: "Regulatory Risk", base: 75, projected: 86 }, { label: "Enterprise GRC", base: 78, projected: 73 }, { label: "Controls Impacted", base: 0, projected: 37 }],
 affected: { bus: 3, controls: 37, policies: 12, mitigations: 8 } },
 { id: "control-reduction", name: "Control Effectiveness Reduction", description: "A 15% drop in control effectiveness across the operational control family.",
 impacts: [{ label: "Operational Risk", base: 82, projected: 88 }, { label: "Residual Reduction", base: 19, projected: 11, unit: "%" }, { label: "Enterprise GRC", base: 78, projected: 71 }],
 affected: { bus: 4, controls: 24, policies: 3, mitigations: 9 } },
 { id: "cost-increase", name: "10% Cost Increase", description: "A broad 10% increase in operating costs stresses financial resilience.",
 impacts: [{ label: "Financial Risk", base: 62, projected: 71 }, { label: "Strategic Risk", base: 57, projected: 64 }, { label: "Exposure", base: 18.4, projected: 24.2, unit: "SAR M" }],
 affected: { bus: 6, controls: 7, policies: 2, mitigations: 5 } },
 { id: "ops-incident", name: "Major Operational Incident", description: "A severe plant incident triggers continuity and safety responses.",
 impacts: [{ label: "Operational Risk", base: 82, projected: 95 }, { label: "People Risk", base: 50, projected: 63 }, { label: "Enterprise GRC", base: 78, projected: 66 }, { label: "Exposure", base: 18.4, projected: 41.5, unit: "SAR M" }],
 affected: { bus: 5, controls: 14, policies: 7, mitigations: 15 } }
];

// Non-destructive what-if levers (adjust local projection only).
export interface Lever {
 id: string;
 label: string;
 min: number;
 max: number;
 default: number;
 unit: string;
 // Effect on projected operational risk score per unit change from default.
 scorePerUnit: number;
}

export const WHATIF_LEVERS: Lever[] = [
 { id: "controlEffectiveness", label: "Control Effectiveness", min: 50, max: 100, default: 72, unit: "%", scorePerUnit: -0.35 },
 { id: "supplierReliability", label: "Supplier Reliability", min: 50, max: 100, default: 78, unit: "%", scorePerUnit: -0.28 },
 { id: "mitigationCompletion", label: "Mitigation Completion", min: 0, max: 100, default: 60, unit: "%", scorePerUnit: -0.18 }
];

export const WHATIF_BASE = { score: 82.1, appetite: 75, tolerance: 85, exposure: 18.4, criticalIssues: 2 };

export interface WhatIfResult {
 score: number;
 exposure: number;
 criticalIssues: number;
 appetiteStatus: string;
}

export function computeWhatIf(values: Record<string, number>): WhatIfResult {
 let delta = 0;
 WHATIF_LEVERS.forEach(l => {
 const v = values[l.id] ?? l.default;
 delta += (v - l.default) * l.scorePerUnit;
 });
 const score = +Math.max(0, Math.min(100, WHATIF_BASE.score + delta)).toFixed(1);
 const exposure = +Math.max(0, WHATIF_BASE.exposure * (1 + delta / 40)).toFixed(1);
 const criticalIssues = Math.max(0, Math.round(WHATIF_BASE.criticalIssues + delta / 4));
 const appetiteStatus = score > WHATIF_BASE.tolerance ? "Above Tolerance" : score > WHATIF_BASE.appetite ? "Outside Appetite" : "Within Appetite";
 return { score, exposure, criticalIssues, appetiteStatus };
}
","import React, { useState } from "react";
