import { SCENARIOS, WHATIF_LEVERS, WHATIF_BASE, computeWhatIf } from "../../data/risk/scenarios";

export function ScenarioAnalysis() {
 const { run } = useActions();
 const [scenarioId, setScenarioId] = useState(SCENARIOS[0].id);
 const [levers, setLevers] = useState<Record<string, number>>(
 WHATIF_LEVERS.reduce((a, l) => ({ ...a, [l.id]: l.default }), {})
 );
 const scenario = SCENARIOS.find(s => s.id === scenarioId)!;
 const result = computeWhatIf(levers);
 const resultSev = result.appetiteStatus === "Within Appetite" ? "healthy" : result.appetiteStatus === "Outside Appetite" ? "high" : "critical";

 return (
 <section className="grc-section">
 <SectionHead icon="diagram-next-outline" title="Scenario Analysis" hint="Projected impact + non-destructive what-if levers (local only — base data never mutated)" />
 <div className="grc-two" style={{ alignItems: "start" }}>
 <Card title="Scenario Impact" icon="diagram-next-outline">
 <div className="grc-chips" style={{ marginBottom: "0.6rem" }}>
 {SCENARIOS.map(s => (
 <button key={s.id} className={`grc-chip grc-chip--btn ${s.id === scenarioId ? "is-active" : ""}`} onClick={() => setScenarioId(s.id)}>{s.name}</button>
 ))}
 </div>
 <p className="grc-section__sub" style={{ marginBottom: "0.5rem" }}>{scenario.description}</p>
 <table className="grc-table">
 <thead><tr><th>Metric</th><th>Base</th><th>Projected</th><th>Δ</th></tr></thead>
 <tbody>
 {scenario.impacts.map(im => (
 <tr key={im.label}>
 <td style={{ fontWeight: 600 }}>{im.label}</td>
 <td>{im.base}{im.unit ? ` ${im.unit}` : ""}</td>
 <td style={{ fontWeight: 700 }}>{im.projected}{im.unit ? ` ${im.unit}` : ""}</td>
 <td><TrendArrow dir={im.projected > im.base ? "up" : im.projected < im.base ? "down" : "flat"} text={`${im.projected > im.base ? "+" : ""}${+(im.projected - im.base).toFixed(1)}`} /></td>
 </tr>
 ))}
 </tbody>
 </table>
 <p className="grc-section__sub" style={{ marginTop: "0.5rem" }}>Affected: {scenario.affected.bus} BUs · {scenario.affected.controls} controls · {scenario.affected.policies} policies · {scenario.affected.mitigations} mitigations</p>
 </Card>

 <Card title="What-If Simulator" icon="sliders-outline">
 {WHATIF_LEVERS.map(l => (
 <div className="grc-lever" key={l.id}>
 <div className="grc-lever__top"><span>{l.label}</span><b>{levers[l.id]}{l.unit}</b></div>
 <input type="range" className="grc-range" min={l.min} max={l.max} value={levers[l.id]}
 onChange={e => setLevers(prev => ({ ...prev, [l.id]: Number(e.target.value) }))} />
 </div>
 ))}
 <div className="grc-whatifout">
 <div className="grc-metric"><span className="grc-metric__label">Projected Risk Score</span><span className="grc-metric__value">{result.score}</span></div>
 <StatusPill severity={resultSev} label={result.appetiteStatus} />
 <div className="grc-metric"><span className="grc-metric__label">Exposure</span><span className="grc-metric__value">SAR {result.exposure}M</span></div>
 <div className="grc-metric"><span className="grc-metric__label">Critical Issues</span><span className="grc-metric__value">{result.criticalIssues}</span></div>
 </div>
 <p className="grc-section__sub"><Icon icon="info-circle-outline" size="sm" /> Base {WHATIF_BASE.score} · appetite {WHATIF_BASE.appetite} · tolerance {WHATIF_BASE.tolerance}. Changes are local only.</p>
 <div className="grc-aibrief__actions">
 <Button label="Save Scenario" variant="secondary" size="sm" onClicked={() => run("Save Scenario")} />
 <Button label="Compare" variant="secondary" size="sm" onClicked={() => run("Compare Scenarios")} />
 <Button label="Create Mitigation Plan" variant="primary" size="sm" onClicked={() => run("Create Mitigation Plan")} />
 </div>
 </Card>
 </div>
 </section>
 );
}
