","import React, { useState } from "react";
import { Card, SectionHead } from "../common/Card";
import { sevColor } from "../viz/severity";
import { RISK_TREND_SERIES, TREND_RANGES, TREND_EVENTS, TrendRange } from "../../data/risk/forecast";

export function RiskTrends() {
 const [range, setRange] = useState<TrendRange>("12m");
 const cfg = TREND_RANGES.find(r => r.id === range)!;
 const start = RISK_TREND_SERIES.length - cfg.points;
 const series = RISK_TREND_SERIES.slice(start);
 const events = TREND_EVENTS.filter(e => e.idx >= start).map(e => ({ ...e, i: e.idx - start }));
 const W = 760, H = 200, pad = 28;
 const min = Math.min(...series) - 2, max = Math.max(...series) + 2, span = max - min || 1;
 const x = (i: number) => pad + (i / (series.length - 1 || 1)) * (W - pad * 2);
 const y = (v: number) => H - pad - ((v - min) / span) * (H - pad * 2);
 const line = series.map((v, i) => `${x(i)},${y(v)}`).join(" L");

 return (
 <section className="grc-section">
 <SectionHead icon="chart-trend-outline" title="Risk Trend Analytics" hint="Enterprise risk score over time with event overlays"
 right={<div className="grc-chips">{TREND_RANGES.map(r => (
 <button key={r.id} className={`grc-chip grc-chip--btn ${r.id === range ? "is-active" : ""}`} onClick={() => setRange(r.id)}>{r.label}</button>
 ))}</div>} />
 <Card>
 <svg width="100%" viewBox={`0 0 ${W} ${H}`} role="img" aria-label="Risk trend with events">
 <path d={`M${line} L${x(series.length - 1)},${H - pad} L${x(0)},${H - pad} Z`} fill={sevColor("watch")} opacity="0.1" />
 <path d={`M${line}`} fill="none" stroke={sevColor("watch")} strokeWidth="2.5" strokeLinecap="round" />
 {series.map((v, i) => <circle key={i} cx={x(i)} cy={y(v)} r="3" fill={sevColor("watch")} />)}
 {events.map(e => (
 <g key={e.idx}>
 <line x1={x(e.i)} y1={pad} x2={x(e.i)} y2={H - pad} stroke={sevColor(e.severity)} strokeDasharray="3 3" strokeWidth="1.5" opacity="0.7" />
 <circle cx={x(e.i)} cy={pad} r="5" fill={sevColor(e.severity)} />
 <text x={x(e.i)} y={pad - 8} textAnchor="middle" className="grc-heatmap__label">{e.date}</text>
 </g>
 ))}
 </svg>
 <div className="grc-eventlegend">
 {events.map(e => (
 <span key={e.idx}><span className="grc-dot" style={{ background: sevColor(e.severity) }} />{e.date} · {e.label}</span>
 ))}
 </div>
 </Card>
 </section>
 );
}
