 <StatusPill severity={PRIO_SEV[r.priority]} label={r.priority} size="sm" />
 </div>
 <p className="grc-insight__reason"><b>Reason: </b>{r.reason}</p>
 <p className="grc-insight__reason"><b>Expected Impact: </b>{r.expectedImpact}</p>
 <div className="grc-rec__meta">
 <span>Owner: {r.owner}</span><span>Due: {r.dueDate}</span>
 <StatusPill severity={OVR_SEV[r.oversight]} label={OVERSIGHT_LABEL[r.oversight]} size="sm" />
 </div>
 <Confidence value={r.confidence} />
 <div className="grc-insight__actions">
 <Button label="Accept" variant="primary" size="sm" onClicked={() => run("Accept Recommendation", `Mock (human-reviewed): accept "${r.title}".`)} />
 <Button label="Modify" variant="secondary" size="sm" onClicked={() => run("Modify Recommendation", `Mock: modify "${r.title}".`)} />
 <Button label="Reject" variant="tertiary" size="sm" onClicked={() => run("Reject Recommendation", `Mock: reject "${r.title}".`)} />
 </div>
 </Card>
 ))}
 </div>
 </section>
 );
}
","import React from "react";
import { Button } from "@servicenow/react-components/Button";
import { Icon } from "@servicenow/react-components/Icon";
import { Card, SectionHead, Metric } from "../common/Card";
import { RadialGauge } from "../viz/Charts";
import { StatusPill } from "../viz/Indicators";
import { useActions } from "../common/Actions";
import { RISK_HERO } from "../../data/risk/overview";
import { TOP_ENTERPRISE_RISKS } from "../../data/risk/overview";
import { RISK_CATEGORIES } from "../../data/risk/categories";
import { KRIS } from "../../data/risk/kris";
import { EMERGING_RISKS } from "../../data/risk/emerging";
import { MITIGATION_SUMMARY } from "../../data/risk/drivers";
import { getForecast } from "../../data/risk/forecast";
import { RISK_RECOMMENDATIONS } from "../../data/risk/emerging";
import { appetiteState } from "../../data/risk/appetite";

export function BriefingMode({ onExit }: { onExit: () => void }) {
 const { run } = useActions();
 const breaches = RISK_CATEGORIES.filter(c => appetiteState(c.currentScore, c.appetite, c.tolerance) !== "within");
 const criticalKris = KRIS.filter(k => k.status === "breached").concat(KRIS.filter(k => k.status === "approaching")).slice(0, 4);
 const f = getForecast("operational")!;
 const gaps = MITIGATION_SUMMARY.plans.filter(m => m.effectivenessPct < 75);

 return (
 <section className="grc-section grc-briefing">
 <SectionHead icon="presentation-outline" title="Executive Briefing Mode" hint="Condensed board view"
 right={<div className="grc-aibrief__actions">
 <Button label="Generate Board Brief" variant="primary" size="sm" icon="document-pdf-outline" onClicked={() => run("Generate Board Brief")} />
 <Button label="Exit Briefing" variant="secondary" size="sm" onClicked={onExit} />
 </div>} />
 <div className="grc-brief-grid">
 <Card title="Overall Risk Posture" icon="dashboard-dial-outline">
 <div className="grc-hero__posture">
 <RadialGauge value={RISK_HERO.exposure} severity="watch" label={`${RISK_HERO.exposure}`} sublabel={RISK_HERO.label} size={110} />
 <div><Metric label="Change" value={`↑ ${RISK_HERO.changePct}%`} /><Metric label="Outside Appetite" value={RISK_HERO.outsideAppetite} /></div>
 </div>
 </Card>
 <Card title="Top 5 Risks" icon="list-outline">
 {TOP_ENTERPRISE_RISKS.slice(0, 5).map(r => <div key={r.id} className="grc-briefrow"><span>#{r.rank} {r.name}</span><b>{r.residual}</b></div>)}
 </Card>
 <Card title="Appetite Breaches" icon="chart-threshold-outline">
 {breaches.map(b => <div key={b.id} className="grc-briefrow"><span>{b.name}</span><StatusPill severity="high" label={`${b.currentScore} / ${b.appetite}`} size="sm" /></div>)}
 </Card>
 <Card title="Critical KRIs" icon="gauge-outline">
 {criticalKris.map(k => <div key={k.id} className="grc-briefrow"><span>{k.name}</span><b>{k.current} {k.unit}</b></div>)}
 </Card>
 <Card title="Risk Forecast" icon="chart-trend-outline">
 <Metric label="Operational 30/60/90" value={`${f.f30} / ${f.f60} / ${f.f90}`} />
 <Metric label="Appetite breach" value={`~${f.appetiteBreachDays} days`} />
 <Metric label="Confidence" value={`${f.confidence}%`} />
 </Card>
 <Card title="Emerging Risks" icon="lightbulb-outline">
 {EMERGING_RISKS.slice(0, 3).map(e => <div key={e.id} className="grc-briefrow"><span>{e.name}</span><b>{e.confidence}%</b></div>)}
 </Card>
 <Card title="Top Mitigation Gaps" icon="wrench-outline">
 {gaps.map(g => <div key={g.id} className="grc-briefrow"><span>{g.name}</span><StatusPill severity="high" label={`${g.effectivenessPct}%`} size="sm" /></div>)}
 </Card>
 <Card title="AI Recommendations" icon="ai-sparkle-fill">
 {RISK_RECOMMENDATIONS.slice(0, 3).map(r => <div key={r.id} className="grc-briefrow"><span>{r.title}</span><Icon icon="ai-sparkle-outline" size="sm" /></div>)}
 </Card>
 </div>
 </section>
 );
}
","import React, { useState } from "react";
import { Button } from "@servicenow/react-components/Button";
import { RiskHero } from "./RiskHero";
import { KeyRiskCategories } from "./KeyRiskCategories";
import { RiskAppetiteMonitor } from "./RiskAppetiteMonitor";
import { RiskHierarchy } from "./RiskHierarchy";
import { KriCenter } from "./KriCenter";
import { PredictiveRisk } from "./PredictiveRisk";
import { RiskContribution } from "./RiskContribution";
import { ScenarioAnalysis } from "./ScenarioAnalysis";
import { EmergingRisks } from "./EmergingRisks";
import { RiskConnectionGraph } from "./RiskConnectionGraph";
import { RiskHeatmapPanel } from "./RiskHeatmapPanel";
import { TopEnterpriseRisks } from "./TopEnterpriseRisks";
import { BuRiskComparison } from "./BuRiskComparison";
import { RiskTrends } from "./RiskTrends";
import { RiskRecommendations } from "./RiskRecommendations";
import { BriefingMode } from "./BriefingMode";
import { DEFAULT_RISK_SUB } from "../../data/risk/subnav";

export function EnterpriseRisk({ sub, onOpenRisk, onOpenTab, onSetSub }: {
 sub: string | null;
 onOpenRisk: (id: string) => void;
 onOpenTab: (tab: string) => void;
 onSetSub: (sub: string) => void;
}) {
 const [briefing, setBriefing] = useState(false);
 const view = sub || DEFAULT_RISK_SUB;

 if (briefing) return <BriefingMode onExit={() => setBriefing(false)} />;

 const toolbar = (
 <div className="grc-risk-toolbar">
 <Button label="Executive Briefing Mode" variant="secondary" size="sm" icon="presentation-outline" onClicked={() => setBriefing(true)} />
 </div>
 );

 if (view === "categories") return <>{toolbar}<KeyRiskCategories onOpen={id => onSetSub("hierarchy")} /><RiskContribution /></>;
 if (view === "appetite") return <>{toolbar}<RiskAppetiteMonitor /></>;
 if (view === "hierarchy") return <>{toolbar}<RiskHierarchy /></>;
 if (view === "kri") return <>{toolbar}<KriCenter /></>;
 if (view === "predictive") return <>{toolbar}<PredictiveRisk /><RiskTrends /></>;
 if (view === "scenario") return <>{toolbar}<ScenarioAnalysis /></>;
 if (view === "emerging") return <>{toolbar}<EmergingRisks /><RiskRecommendations /><RiskConnectionGraph onNavigate={onOpenTab} /></>;

 // overview (default) — executive dashboard
 return (
 <>
 {toolbar}
 <RiskHero onExplain={() => onSetSub("categories")} onViewRisks={() => onSetSub("hierarchy")} onRunScenario={() => onSetSub("scenario")} />
 <KeyRiskCategories compact onOpen={() => onSetSub("categories")} />
 <RiskHeatmapPanel onOpenRisk={onOpenRisk} />
 <TopEnterpriseRisks onOpenRisk={onOpenRisk} />
 <BuRiskComparison />
 <RiskTrends />
 </>
 );
}
