 );
}
","// Unified risk resolver for the Risk Detail Drawer.
import { TOP_ENTERPRISE_RISKS } from "./overview";
import { RISK_BUBBLES } from "../mockData";
import { findNode } from "./hierarchy";
import { RISK_CATEGORIES } from "./categories";

export interface ResolvedRisk {
 id: string;
 name: string;
 category: string;
 bu: string;
 residual: number;
 appetite: number;
 velocity: string;
 triggeredKRIs: number;
 controlEffectiveness: number;
 exposure: number;
 owner: string;
 trend: "up" | "down" | "flat";
 relationshipId?: string; // id usable with relationships.getRelated
}

export function resolveRisk(id: string): ResolvedRisk | undefined {
 const top = TOP_ENTERPRISE_RISKS.find(r => r.id === id);
 if (top) {
 return { id, name: top.name, category: top.category, bu: top.bu, residual: top.residual, appetite: top.appetite, velocity: top.velocity, triggeredKRIs: top.triggeredKRIs, controlEffectiveness: top.controlEffectiveness, exposure: top.exposure, owner: top.owner, trend: top.trend, relationshipId: RISK_BUBBLES.find(b => b.name.includes(top.name.split(" ")[0]))?.id };
 }
 const bubble = RISK_BUBBLES.find(b => b.id === id);
 if (bubble) {
 const cat = RISK_CATEGORIES.find(c => c.name === bubble.category);
 return { id, name: bubble.name, category: bubble.category, bu: bubble.bu, residual: cat?.residualScore ?? 70, appetite: cat?.appetite ?? 70, velocity: cat?.velocity ?? "moderate", triggeredKRIs: cat?.triggeredKRIs ?? 1, controlEffectiveness: cat?.controlEffectiveness ?? 75, exposure: bubble.exposure, owner: "Risk Owner", trend: "up", relationshipId: bubble.id };
 }
 const node = findNode(id);
 if (node) {
 return { id, name: node.name, category: "Operational", bu: node.name, residual: node.score, appetite: 75, velocity: "moderate", triggeredKRIs: node.kris, controlEffectiveness: 72, exposure: 50, owner: node.owner, trend: node.trend };
 }
 return undefined;
}

export const RISK_AI_ANALYSIS = [
 { q: "Why is this risk changing?", a: "Residual risk is rising as control effectiveness slips and leading KRIs accelerate toward threshold." },
 { q: "What are the main drivers?", a: "Control failures (42%), supplier deterioration (23%) and KRI movement (18%) dominate the increase." },
 { q: "What happens next?", a: "Without intervention the risk is forecast to breach appetite within ~21 days (87% confidence)." },
 { q: "Which controls are weak?", a: "Asset Redundancy (69%) and Supplier Qualification (78%) are the weakest contributing controls." },
 { q: "Is remediation delayed?", a: "The Dual Supplier Strategy mitigation is underperforming (65% of expected reduction)." },
 { q: "What should I do?", a: "Activate a secondary supplier, fast-track preventive maintenance, and recalibrate Operations KRI thresholds." }
];
","import React, { useEffect } from "react";
import { Button } from "@servicenow/react-components/Button";
import { Icon } from "@servicenow/react-components/Icon";
import { StatusPill, TrendArrow } from "../viz/Indicators";
import { useActions } from "../common/Actions";
import { resolveRisk, RISK_AI_ANALYSIS } from "../../data/risk/resolve";
import { RISK_ACTIONS } from "../../data/risk/emerging";
import { getRelated, RelatedRef } from "../../data/relationships";
import { appetiteState, appetiteStateSeverity, APPETITE_STATE_LABEL } from "../../data/risk/appetite";
import { VELOCITY_LABEL, Velocity } from "../../data/risk/categories";

function Field({ label, value }: { label: string; value: React.ReactNode }) {
 return <div className="grc-field"><span className="grc-field__label">{label}</span><span className="grc-field__value">{value}</span></div>;
}

const TAB_FOR: Record<string, string> = { control: "controls", policy: "governance", regulation: "regulatory", issue: "controls", remediation: "risk", assurance: "assurance", kri: "risk", bu: "risk", risk: "risk" };

export function RiskDrawer({ riskId, onClose, onOpenTab }: { riskId: string; onClose: () => void; onOpenTab: (tab: string) => void }) {
 const { run } = useActions();
 const risk = resolveRisk(riskId);

 useEffect(() => {
 const onKey = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
 document.addEventListener("keydown", onKey);
 return () => document.removeEventListener("keydown", onKey);
 }, [onClose]);

 if (!risk) return null;
 const state = appetiteState(risk.residual, risk.appetite, risk.appetite + 10);
 const sev = appetiteStateSeverity(state);
 const related: RelatedRef[] = risk.relationshipId ? getRelated("risk", risk.relationshipId) : [];

 return (
 <>
 <div className="grc-drawer-overlay" onClick={onClose} />
 <aside className="grc-drawer" role="dialog" aria-label="Risk detail">
 <div className="grc-drawer__head">
 <div>
 <div className="grc-drawer__title">{risk.name}</div>
 <div style={{ marginTop: 6, display: "flex", gap: 6, flexWrap: "wrap", alignItems: "center" }}>
 <StatusPill severity={sev} label={APPETITE_STATE_LABEL[state]} size="sm" />
 <StatusPill severity="neutral" label={risk.category} size="sm" />
 <TrendArrow dir={risk.trend} text={VELOCITY_LABEL[risk.velocity as Velocity]} />
 </div>
 </div>
 <button className="grc-iconbtn" aria-label="Close" onClick={onClose}><Icon icon="close-outline" size="md" /></button>
 </div>

 <div className="grc-drawer__body">
 <div className="grc-fieldgrid">
 <Field label="Residual Score" value={<b className="grc-drawer__kpival">{risk.residual}</b>} />
 <Field label="Appetite" value={risk.appetite} />
 <Field label="Business Unit" value={risk.bu} />
 <Field label="Owner" value={risk.owner} />
 <Field label="Triggered KRIs" value={risk.triggeredKRIs} />
 <Field label="Control Effectiveness" value={`${risk.controlEffectiveness}%`} />
 <Field label="Financial Exposure" value={<span className="grc-exposure">SAR {risk.exposure}M</span>} />
 <Field label="Velocity" value={VELOCITY_LABEL[risk.velocity as Velocity]} />
 </div>

 {related.length ? (
 <div className="grc-field">
 <span className="grc-field__label">Related (click to navigate)</span>
 <div className="grc-chips">
 {related.map(r => (
 <button key={r.type + r.id} className="grc-chip grc-chip--btn" onClick={() => onOpenTab(TAB_FOR[r.type] || "risk")}>
 <span className="grc-chip__type">{r.type}</span> {r.label}
 </button>
 ))}
 </div>
 </div>
 ) : null}

 <div className="grc-aiblock">
 <span className="grc-aibrief__tag"><Icon icon="ai-sparkle-fill" size="sm" /> AI RISK ANALYSIS</span>
 {RISK_AI_ANALYSIS.map((qa, i) => (
 <div key={i}>
 <div className="grc-aiqa__q"><Icon icon="circle-question-outline" size="sm" />{qa.q}</div>
 <p className="grc-aiqa__a">{qa.a}</p>
 </div>
 ))}
 </div>
 </div>

 <div className="grc-drawer__foot">
 {RISK_ACTIONS.map(a => (
 <Button key={a} label={a} size="sm"
 variant={a === "Accept AI Recommendation" ? "primary" : a === "Escalate Risk" ? "primary-negative" : "secondary"}
 onClicked={() => run(a, `Mock action: "${a}" for risk "${risk.name}".`)} />
 ))}
 </div>
 </aside>
 </>
 );
}
